(5789641, 841628, 15711, '<td valign="top">I love how the horse on the left is peering into the shot.  Great one.  Is that you, Jeb?</td>', 'I love how the horse on the left is peering into the shot.  Great one.  Is that you, Jeb?', '2010-01-01 10:20:50.000000', NULL, 1),
(5789643, 843231, 27608, '<td valign="top">All I have to say is awesome!  Great placement of the falls and the lower lookout.  The ice and angle really makes this shot unique!</td>', 'All I have to say is awesome!  Great placement of the falls and the lower lookout.  The ice and angle really makes this shot unique!', '2010-01-01 10:21:14.000000', NULL, 1),
(5789644, 839075, 15711, '<td valign="top">A bit posed for my taste but so well done nonetheless.  I love the tonal range and the focus is perfect.  Man, that kid has some eyes!!</td>', 'A bit posed for my taste but so well done nonetheless.  I love the tonal range and the focus is perfect.  Man, that kid has some eyes!!', '2010-01-01 10:21:23.000000', NULL, 1),
