(5791956, 841140, 62187, '<td valign="top">};&gt;)</td>', '};>)', '2010-01-02 20:09:33.000000', NULL, 1),
(5791961, 843231, 111808, '<td valign="top">This almost looks like it was done on a miniature scale, so powerful and mighty are the falls in comparison to the smaller manmade building. The blended white tones of the water combine so beautifully with the frost tones of the surrounding immediate landscape complemented by the high-key icicles hanging down in short, orderly rows against the greystone rocks. These are even echoed with icicles hanging down from the ornate building above. Superb winter landscape.</td>', 'This almost looks like it was done on a miniature scale, so powerful and mighty are the falls in comparison to the smaller manmade building. The blended white tones of the water combine so beautifully with the frost tones of the surrounding immediate landscape complemented by the high-key icicles hanging down in short, orderly rows against the greystone rocks. These are even echoed with icicles hanging down from the ornate building above. Superb winter landscape.', '2010-01-02 20:17:45.000000', NULL, 1),
(5791969, 842012, 30669, '<td valign="top">Incredible shot....10</td>', 'Incredible shot....10', '2010-01-02 20:26:25.000000', NULL, 1),
(5791982, 842946, 30669, '<td valign="top">Wow. Wonderful shot... 10</td>', 'Wow. Wonderful shot... 10', '2010-01-02 20:29:58.000000', NULL, 1),
(5791990, 843252, 11854, '<td valign="top">Back to comment...<br/> <br/>Gorgeous scene! Lovely, saturated colors and awesome detail give it a painterly feel. 10</td>', 'Back to comment... Gorgeous scene! Lovely, saturated colors and awesome detail give it a painterly feel. 10', '2010-01-02 20:34:19.000000', NULL, 1),
(5791991, 842203, 11854, '<td valign="top">Back to comment...<br/> <br/>Beautiful wide angle view! Love all the shapes in this one! 10</td>', 'Back to comment... Beautiful wide angle view! Love all the shapes in this one! 10', '2010-01-02 20:35:45.000000', NULL, 1),
(5791993, 841701, 11854, '<td valign="top">Back to comment...<br/> <br/>What a wonderful, mysterious story unfolding! 10</td>', 'Back to comment... What a wonderful, mysterious story unfolding! 10', '2010-01-02 20:36:36.000000', NULL, 1),
(5791997, 842926, 57447, '<td valign="top">Good job on the lighting.  Can''t wait to see what you enter for the annual pet challenge.</td>', 'Good job on the lighting.  Can''t wait to see what you enter for the annual pet challenge.', '2010-01-02 20:38:57.000000', NULL, 1),
(5791998, 842995, 100831, '<td valign="top">Beautiful!! Gorgeous colors and light. 8</td>', 'Beautiful!! Gorgeous colors and light. 8', '2010-01-02 20:39:20.000000', NULL, 1),
(5791999, 843217, 57447, '<td valign="top">Will make a great stock photo.</td>', 'Will make a great stock photo.', '2010-01-02 20:39:27.000000', NULL, 1),
(5792001, 842925, 100831, '<td valign="top">I''m guessing this might be an overlay of some sort? I really like it, particularly in b/w. 8</td>', 'I''m guessing this might be an overlay of some sort? I really like it, particularly in b/w. 8', '2010-01-02 20:40:10.000000', NULL, 1),
(5792003, 842937, 100831, '<td valign="top">Beautiful colors and excellent wide angle helps to make this a dramatic photograph. Love it! 8</td>', 'Beautiful colors and excellent wide angle helps to make this a dramatic photograph. Love it! 8', '2010-01-02 20:41:11.000000', NULL, 1),
(5792004, 841707, 100831, '<td valign="top">Stunning...</td>', 'Stunning...', '2010-01-02 20:41:29.000000', NULL, 1),
(5792005, 843257, 100831, '<td valign="top">Very nice, colorful abstract. Well done framing. 7</td>', 'Very nice, colorful abstract. Well done framing. 7', '2010-01-02 20:41:53.000000', NULL, 1),
(5792007, 841793, 100831, '<td valign="top">Beautiful portrait - nicely composed.</td>', 'Beautiful portrait - nicely composed.', '2010-01-02 20:42:35.000000', NULL, 1),
(5792008, 843317, 100831, '<td valign="top">Nice processing to get this to stand out. Lovely colors and textures. 7</td>', 'Nice processing to get this to stand out. Lovely colors and textures. 7', '2010-01-02 20:43:21.000000', NULL, 1),
(5792011, 842854, 30669, '<td valign="top">Very sexy</td>', 'Very sexy', '2010-01-02 20:43:43.000000', NULL, 1),
(5792012, 839292, 100831, '<td valign="top">Nice contrasts in tone and shape. Great motion and light. 8</td>', 'Nice contrasts in tone and shape. Great motion and light. 8', '2010-01-02 20:44:03.000000', NULL, 1),
(5792014, 842928, 30669, '<td valign="top">Iceland???? Great shot.</td>', 'Iceland???? Great shot.', '2010-01-02 20:44:47.000000', NULL, 1),
(5792016, 843244, 100831, '<td valign="top">Interesting silhouette nicely leading into the frame. Lovely background and bokeh.</td>', 'Interesting silhouette nicely leading into the frame. Lovely background and bokeh.', '2010-01-02 20:45:35.000000', NULL, 1),
(5792017, 840383, 30669, '<td valign="top">South Haven lighthouse????<br/> <br/>Wonderful shot.......10</td>', 'South Haven lighthouse???? Wonderful shot.......10', '2010-01-02 20:45:59.000000', NULL, 1),
(5792018, 841999, 100831, '<td valign="top">Gorgeous eyes. Excellent portrait work.</td>', 'Gorgeous eyes. Excellent portrait work.', '2010-01-02 20:46:15.000000', NULL, 1),
(5792019, 841567, 100831, '<td valign="top">This is special. And so nicely done.</td>', 'This is special. And so nicely done.', '2010-01-02 20:47:29.000000', NULL, 1),
(5792020, 839545, 100831, '<td valign="top">I love the selective focus, the color, and the interesting shapes - hope this does well.</td>', 'I love the selective focus, the color, and the interesting shapes - hope this does well.', '2010-01-02 20:49:03.000000', NULL, 1),
(5792021, 843106, 57447, '<td valign="top">Simple photo that is impressive.</td>', 'Simple photo that is impressive.', '2010-01-02 20:50:00.000000', NULL, 1),
(5792022, 843227, 100831, '<td valign="top">Oh so peaceful.... what stunning scenery. Nicely done. 7</td>', 'Oh so peaceful.... what stunning scenery. Nicely done. 7', '2010-01-02 20:50:07.000000', NULL, 1),
(5792025, 843229, 100831, '<td valign="top">Interesting color and motion. It almost looks like a pottery wheel.</td>', 'Interesting color and motion. It almost looks like a pottery wheel.', '2010-01-02 20:52:01.000000', NULL, 1),
(5792026, 842989, 30669, '<td valign="top">Wow!</td>', 'Wow!', '2010-01-02 20:52:41.000000', NULL, 1),
(5792037, 843108, 111808, '<td valign="top">I like how the angles of the path railing draw you into this photograph and how they are repeated off into the far perspective. The black and white tones work well for this because of the starkness of the winter snow against the darker patterned bricks. The hanging vines give this a subtle touch of surrealism amidst the serenity.</td>', 'I like how the angles of the path railing draw you into this photograph and how they are repeated off into the far perspective. The black and white tones work well for this because of the starkness of the winter snow against the darker patterned bricks. The hanging vines give this a subtle touch of surrealism amidst the serenity.', '2010-01-02 21:04:18.000000', NULL, 1),
(5792039, 838577, 77838, '<td valign="top">A beautiful model; I like how her eye''s are closed.  Almost as if lost in thought.  BB</td>', 'A beautiful model; I like how her eye''s are closed.  Almost as if lost in thought.  BB', '2010-01-02 21:04:52.000000', NULL, 1),
(5792044, 841313, 87252, '<td valign="top">Wow this is a really expansive shot, you get a wonderful sense of space.</td>', 'Wow this is a really expansive shot, you get a wonderful sense of space.', '2010-01-02 21:06:19.000000', NULL, 1),
(5792045, 842623, 87252, '<td valign="top">Fabulous natural lighting, great comp and excellent subject.</td>', 'Fabulous natural lighting, great comp and excellent subject.', '2010-01-02 21:07:31.000000', NULL, 1),
(5792046, 838621, 87252, '<td valign="top">I like the rainbows in the waves but the horizon is a bit wonky, and you could do with pumping the contrast a bit to bring out the details in the hills.</td>', 'I like the rainbows in the waves but the horizon is a bit wonky, and you could do with pumping the contrast a bit to bring out the details in the hills.', '2010-01-02 21:08:50.000000', NULL, 1),
(5792047, 843091, 87252, '<td valign="top">Sweet shot, this''ll make a really nice print, the focus is maybe a little soft to score very highly though.</td>', 'Sweet shot, this''ll make a really nice print, the focus is maybe a little soft to score very highly though.', '2010-01-02 21:10:06.000000', NULL, 1),
(5792052, 843123, 87252, '<td valign="top">Great scene, my main thought for improvement would be a deeper depth of field to bring out the details in the nearby rocks. Also this might havea been a good candidate for HDR treatment to bring a bit of detail out of the shadows.</td>', 'Great scene, my main thought for improvement would be a deeper depth of field to bring out the details in the nearby rocks. Also this might havea been a good candidate for HDR treatment to bring a bit of detail out of the shadows.', '2010-01-02 21:12:57.000000', NULL, 1),
(5792054, 843011, 87252, '<td valign="top">Wow cool, almost looks like a painting.</td>', 'Wow cool, almost looks like a painting.', '2010-01-02 21:13:29.000000', NULL, 1),
(5792056, 840383, 57447, '<td valign="top">Brrr...goooood shhhooottt.</td>', 'Brrr...goooood shhhooottt.', '2010-01-02 21:15:26.000000', NULL, 1),
(5792058, 842801, 87252, '<td valign="top">This is pretty cool - unfortunately I feel you may be in for a DQ because of the text.</td>', 'This is pretty cool - unfortunately I feel you may be in for a DQ because of the text.', '2010-01-02 21:16:28.000000', NULL, 1),
(5792060, 839478, 111808, '<td valign="top">How stark, how simple, how beautiful this is with each single dewdrop reflecting the worlds behind it like an elegant miniature ball of finest crystal. How intricate the connected patterns of the webspinner combine to make a fine filamented cohesive net, like pearls sparkling against the quiet background. Kudos to you for the excellent capture.</td>', 'How stark, how simple, how beautiful this is with each single dewdrop reflecting the worlds behind it like an elegant miniature ball of finest crystal. How intricate the connected patterns of the webspinner combine to make a fine filamented cohesive net, like pearls sparkling against the quiet background. Kudos to you for the excellent capture.', '2010-01-02 21:16:51.000000', NULL, 1),
(5792063, 843351, 87252, '<td valign="top">Very cute.</td>', 'Very cute.', '2010-01-02 21:17:28.000000', NULL, 1),
(5792064, 839545, 87252, '<td valign="top">I love this kind of abstract, focus could have been a little sharper but I like the composition.</td>', 'I love this kind of abstract, focus could have been a little sharper but I like the composition.', '2010-01-02 21:18:16.000000', NULL, 1),
(5792068, 843127, 111808, '<td valign="top">Love how the repeating abstract windows framed by the warm golden bricks make a zigzagged larger pattern of pure graphic design. The lighting on this is just perfect to emphasize the lines.</td>', 'Love how the repeating abstract windows framed by the warm golden bricks make a zigzagged larger pattern of pure graphic design. The lighting on this is just perfect to emphasize the lines.', '2010-01-02 21:19:38.000000', NULL, 1),
(5792069, 843348, 93565, '<td valign="top">Haha. Nice action capture- the pose is excellent. I would like to have seen things from a bit wider perspective though, in order to get the scale of the wave crashing and just to improve perspective a bit. It feels like I''m being swallowed by the wave like the surfer as well, and I''d prefer to see the magnitude of how much the surfer is being swallowed, if you get me. Still good.</td>', 'Haha. Nice action capture- the pose is excellent. I would like to have seen things from a bit wider perspective though, in order to get the scale of the wave crashing and just to improve perspective a bit. It feels like I''m being swallowed by the wave like the surfer as well, and I''d prefer to see the magnitude of how much the surfer is being swallowed, if you get me. Still good.', '2010-01-02 21:20:28.000000', NULL, 1),
(5792071, 843022, 86799, '<td valign="top">Very nice abstract - bright, colorful, engaging.  Good work.</td>', 'Very nice abstract - bright, colorful, engaging.  Good work.', '2010-01-02 21:21:54.000000', NULL, 1),
(5792076, 841642, 86799, '<td valign="top">Lighting is very harsh.  She seems to be very out of place without a reason.</td>', 'Lighting is very harsh.  She seems to be very out of place without a reason.', '2010-01-02 21:24:15.000000', NULL, 1),
(5792077, 842878, 93565, '<td valign="top">Nice city scene. Quite a few people out despite the weather. I''m left wondering a bit on what the key subject is in the scene though; what should the viewer focus upon? Perhaps zooming in on the crowds of people more, or emphasizing the building facades more? It just doesn''t seem as though you''ve focused upon a particular aspect of the scene.</td>', 'Nice city scene. Quite a few people out despite the weather. I''m left wondering a bit on what the key subject is in the scene though; what should the viewer focus upon? Perhaps zooming in on the crowds of people more, or emphasizing the building facades more? It just doesn''t seem as though you''ve focused upon a particular aspect of the scene.', '2010-01-02 21:24:38.000000', NULL, 1),
(5792083, 842901, 93565, '<td valign="top">Bird captures are really tough. Between lugging a gigantic lens around and their flighty nature, it''s difficult to get the composition one wants. You got a bit of action here with the screech, but I feel like the moment the eagle lighted or landed from its perch would have had a far stronger impact, which is crucial to Free Studies. Nice detail on the bird though.</td>', 'Bird captures are really tough. Between lugging a gigantic lens around and their flighty nature, it''s difficult to get the composition one wants. You got a bit of action here with the screech, but I feel like the moment the eagle lighted or landed from its perch would have had a far stronger impact, which is crucial to Free Studies. Nice detail on the bird though.', '2010-01-02 21:28:14.000000', NULL, 1),
(5792084, 843085, 111808, '<td valign="top">What a magnificent frozen waterfall with the small touches of golden sweetlight repeating on the treetops and touching the rocks. The snow sets off the warm &amp; veined brown tones of the rocks in a beautiful complement and the angle of the larger one is a perfect frame for the scene as well. The lower jagged edges of the main rock echoes the uneven diagonal of the treeline and draws the eye up to the darker towering pines. A hint of blue sky makes promises that while this Winter might be cold, it is not necessarily long and there will be small savored moments of pure Magick along the way.</td>', 'What a magnificent frozen waterfall with the small touches of golden sweetlight repeating on the treetops and touching the rocks. The snow sets off the warm & veined brown tones of the rocks in a beautiful complement and the angle of the larger one is a perfect frame for the scene as well. The lower jagged edges of the main rock echoes the uneven diagonal of the treeline and draws the eye up to the darker towering pines. A hint of blue sky makes promises that while this Winter might be cold, it is not necessarily long and there will be small savored moments of pure Magick along the way.', '2010-01-02 21:28:19.000000', NULL, 1),
(5792085, 842647, 86799, '<td valign="top">Great DOF, detail and color.  Interesting pattern and size.</td>', 'Great DOF, detail and color.  Interesting pattern and size.', '2010-01-02 21:29:05.000000', NULL, 1),
(5792087, 842736, 86799, '<td valign="top">Outstanding.</td>', 'Outstanding.', '2010-01-02 21:29:15.000000', NULL, 1),
(5792088, 842742, 87252, '<td valign="top">Cool idea and nice starfish! I could be very wrong here but it looks as though you might have lit this shot with a flash from the sand, I just can''t figure out where the light is coming from in relation to the shadows - I''ve been staring at it for about 10 minutes! :) I also think this shot may have benefited from a square crop, the horizon is a bit featureless and doesn''t add all that much.</td>', 'Cool idea and nice starfish! I could be very wrong here but it looks as though you might have lit this shot with a flash from the sand, I just can''t figure out where the light is coming from in relation to the shadows - I''ve been staring at it for about 10 minutes! :) I also think this shot may have benefited from a square crop, the horizon is a bit featureless and doesn''t add all that much.', '2010-01-02 21:29:35.000000', NULL, 1),
(5792091, 838589, 87252, '<td valign="top">Nice one, I think your horizon might be ever so slightly wonky though!</td>', 'Nice one, I think your horizon might be ever so slightly wonky though!', '2010-01-02 21:30:15.000000', NULL, 1),
(5792093, 841497, 86799, '<td valign="top">Bold and beautiful.  A little more sharpness to the back of field would have made this incredible.  Still, very nice.</td>', 'Bold and beautiful.  A little more sharpness to the back of field would have made this incredible.  Still, very nice.', '2010-01-02 21:30:24.000000', NULL, 1),
(5792095, 842838, 86799, '<td valign="top">Simple image, works well with blur and noise.  Nice.</td>', 'Simple image, works well with blur and noise.  Nice.', '2010-01-02 21:30:42.000000', NULL, 1),
(5792096, 843005, 87252, '<td valign="top">Great shot - I have a painting which looks just like this.</td>', 'Great shot - I have a painting which looks just like this.', '2010-01-02 21:30:56.000000', NULL, 1),
(5792097, 842197, 86799, '<td valign="top">VERY nice catch.  Once in a lifetime shot, caught sharp and dramatic.  Cool.  Good work.</td>', 'VERY nice catch.  Once in a lifetime shot, caught sharp and dramatic.  Cool.  Good work.', '2010-01-02 21:31:27.000000', NULL, 1),
(5792099, 841653, 86799, '<td valign="top">Very nice.  The pot looks "slightly" tipped, but apparently isn''t.  Good lines and curves, soft and inviting.  Pleasing to the eye.</td>', 'Very nice.  The pot looks "slightly" tipped, but apparently isn''t.  Good lines and curves, soft and inviting.  Pleasing to the eye.', '2010-01-02 21:31:46.000000', NULL, 1),
(5792100, 843115, 111808, '<td valign="top">I like the perspective of this and the tones of the water against the grey.<br/>I also like the repeating even line patterns and how the journey across is marked by light at the end.</td>', 'I like the perspective of this and the tones of the water against the grey.I also like the repeating even line patterns and how the journey across is marked by light at the end.', '2010-01-02 21:32:01.000000', NULL, 1),
(5792104, 843238, 87252, '<td valign="top">Lorsqu''il te menace!</td>', 'Lorsqu''il te menace!', '2010-01-02 21:34:30.000000', NULL, 1),
(5792105, 840929, 86799, '<td valign="top">Great curves and shapes and contrasts.  Has to be my favorite of the free study.</td>', 'Great curves and shapes and contrasts.  Has to be my favorite of the free study.', '2010-01-02 21:34:37.000000', NULL, 1),
(5792107, 841037, 86799, '<td valign="top">Soft beauty and "peace".  I like this one a lot, should be in top 10 IMO.</td>', 'Soft beauty and "peace".  I like this one a lot, should be in top 10 IMO.', '2010-01-02 21:35:40.000000', NULL, 1),
(5792108, 842995, 86799, '<td valign="top">Excellent.</td>', 'Excellent.', '2010-01-02 21:35:49.000000', NULL, 1),
(5792109, 842946, 86799, '<td valign="top">Should be in top 10, IMO.  Very dramatic.</td>', 'Should be in top 10, IMO.  Very dramatic.', '2010-01-02 21:36:20.000000', NULL, 1),
(5792114, 842985, 87252, '<td valign="top">Nice urban decay-y shot, great building. Small point for improvement would be crop the building more tightly to leave out unimportant background details.</td>', 'Nice urban decay-y shot, great building. Small point for improvement would be crop the building more tightly to leave out unimportant background details.', '2010-01-02 21:37:56.000000', NULL, 1),
(5792116, 840997, 16197, '<td valign="top">I enjoy the composition here.  however the colours and contrasts do not work well for me.  I am wondering what other times of day would look like as well as if there are lights for maybe a nighttime shot? Hmm.  It has potential just not for me today.</td>', 'I enjoy the composition here.  however the colours and contrasts do not work well for me.  I am wondering what other times of day would look like as well as if there are lights for maybe a nighttime shot? Hmm.  It has potential just not for me today.', '2010-01-02 21:38:05.000000', NULL, 1),
(5792118, 841456, 16197, '<td valign="top">Interesting image.  The editing style makes it feel very manufactured and created digitally.  For me I feel any sense of realism to the image.  It is a nice image but for me it just does not blow me away as a photograph.</td>', 'Interesting image.  The editing style makes it feel very manufactured and created digitally.  For me I feel any sense of realism to the image.  It is a nice image but for me it just does not blow me away as a photograph.', '2010-01-02 21:38:13.000000', NULL, 1),
(5792119, 840502, 87252, '<td valign="top">Lovely, I really like the minimalism.</td>', 'Lovely, I really like the minimalism.', '2010-01-02 21:38:23.000000', NULL, 1),
(5792122, 842486, 16197, '<td valign="top">This is a lovely image.  Nice simple sunset behind the clouds on the beach.  Everything is nice about this image.  Though there really is no real eyecandy to blow me away with.  This image is nice, possibly even commercial nice for religious stuff.  Just not very exciting for me personally.</td>', 'This is a lovely image.  Nice simple sunset behind the clouds on the beach.  Everything is nice about this image.  Though there really is no real eyecandy to blow me away with.  This image is nice, possibly even commercial nice for religious stuff.  Just not very exciting for me personally.', '2010-01-02 21:39:31.000000', NULL, 1),
(5792124, 841733, 87252, '<td valign="top">Great model, I think the BW conversion blows her skin out just a bit too much. I probably wouldn''t have done it differently, I like this look, but it''s perhaps not very DPC.</td>', 'Great model, I think the BW conversion blows her skin out just a bit too much. I probably wouldn''t have done it differently, I like this look, but it''s perhaps not very DPC.', '2010-01-02 21:40:39.000000', NULL, 1),
(5792125, 841680, 16197, '<td valign="top">The depth of contrast on the tree/bush thing is interesting.  Though for me it is not interesting enough.  The title with the little half moon seems almost misplaced.  The piece just does not hold me.</td>', 'The depth of contrast on the tree/bush thing is interesting.  Though for me it is not interesting enough.  The title with the little half moon seems almost misplaced.  The piece just does not hold me.', '2010-01-02 21:41:06.000000', NULL, 1),
(5792127, 843137, 87252, '<td valign="top">Really cool, shame you can''t really see the ciggie smoke against the white background.</td>', 'Really cool, shame you can''t really see the ciggie smoke against the white background.', '2010-01-02 21:41:53.000000', NULL, 1),
(5792128, 843173, 111808, '<td valign="top">How effective that this off paned window offers only pieces of the view beyond it which pretty much echoes the view of the one through which we look. Some of it is stark and lined, repeated glimpses on a level of class.  The frosted ones admit only another point kind of reality. The pitch black frame of the casing enhances what colours we do see. Are we held in by it or kept out?</td>', 'How effective that this off paned window offers only pieces of the view beyond it which pretty much echoes the view of the one through which we look. Some of it is stark and lined, repeated glimpses on a level of class.  The frosted ones admit only another point kind of reality. The pitch black frame of the casing enhances what colours we do see. Are we held in by it or kept out?', '2010-01-02 21:41:55.000000', NULL, 1),
(5792129, 842922, 16197, '<td valign="top">This hurts my eyes.  The manufactured ''dreamy'' effect is completely misplaced in this challenge.  The image stopped looking like a photograph and is now looking as a digital illustration or drawing.  Im sure this type of processing has its place but for me, here, it is completely misplaced.</td>', 'This hurts my eyes.  The manufactured ''dreamy'' effect is completely misplaced in this challenge.  The image stopped looking like a photograph and is now looking as a digital illustration or drawing.  Im sure this type of processing has its place but for me, here, it is completely misplaced.', '2010-01-02 21:42:31.000000', NULL, 1),
(5792132, 843223, 87252, '<td valign="top">Wow that is one rock and roll Zebra! He looks like Rod Stewart bred with a barcode.</td>', 'Wow that is one rock and roll Zebra! He looks like Rod Stewart bred with a barcode.', '2010-01-02 21:43:45.000000', NULL, 1),
(5792133, 843159, 16197, '<td valign="top">The idea here is nice.  The lighting almost works, but for me the distance seems too short between camera and bend.  Also I would have liked to see more of those wonderful branches going overhead instead of such stark darkness.</td>', 'The idea here is nice.  The lighting almost works, but for me the distance seems too short between camera and bend.  Also I would have liked to see more of those wonderful branches going overhead instead of such stark darkness.', '2010-01-02 21:43:49.000000', NULL, 1),
(5792134, 843171, 111808, '<td valign="top">Excellent portrait - I wish for him the best in Life and hope he remains safe in the execution of his duties.</td>', 'Excellent portrait - I wish for him the best in Life and hope he remains safe in the execution of his duties.', '2010-01-02 21:44:48.000000', NULL, 1),
(5792135, 842930, 87252, '<td valign="top">Sick! Not convinced DPC voters will see the humour in this - brave entry.</td>', 'Sick! Not convinced DPC voters will see the humour in this - brave entry.', '2010-01-02 21:44:52.000000', NULL, 1),
(5792136, 843180, 16197, '<td valign="top">Nice clean black/white portrait.  Im sure the model is extremely happy with this, because she does look good.  The image looks good as a whole.  Though for a free study challenge I would hope for something with a bit more behind it.  Something more dramatic and exciting.  But like I said it is a nice portrait, just not enough for me.</td>', 'Nice clean black/white portrait.  Im sure the model is extremely happy with this, because she does look good.  The image looks good as a whole.  Though for a free study challenge I would hope for something with a bit more behind it.  Something more dramatic and exciting.  But like I said it is a nice portrait, just not enough for me.', '2010-01-02 21:45:09.000000', NULL, 1),
(5792140, 843297, 16197, '<td valign="top">A classic style of image.  I have seen many, some better some worse.  Even though it can make for a fun shot to show off to your friends who have not been.  For me, it just does not wow me enough.  I would love to see something different, something more out of the box exciting.</td>', 'A classic style of image.  I have seen many, some better some worse.  Even though it can make for a fun shot to show off to your friends who have not been.  For me, it just does not wow me enough.  I would love to see something different, something more out of the box exciting.', '2010-01-02 21:46:38.000000', NULL, 1),
(5792142, 841679, 16197, '<td valign="top">Cute snapshot of the cats.  It appears fairly clear and such.  However being detached from the image it just does not appeal to me.  No wow factor or drama or excitement to hold my attention.</td>', 'Cute snapshot of the cats.  It appears fairly clear and such.  However being detached from the image it just does not appeal to me.  No wow factor or drama or excitement to hold my attention.', '2010-01-02 21:47:39.000000', NULL, 1),
(5792148, 843276, 87252, '<td valign="top">Ha! Fab, looks like they might have fallen out, no doubt a massive social faux-pas on the part of the Elephant.</td>', 'Ha! Fab, looks like they might have fallen out, no doubt a massive social faux-pas on the part of the Elephant.', '2010-01-02 21:48:56.000000', NULL, 1),
(5792151, 842836, 16197, '<td valign="top">I have seen several similar types of images in this challenge so far.  However I have to say this one is more true photograph then some of the others.  Yet it still is just middle of the road for me.  After seeing so many of these types of images, no matter the location, the center composition mirrored sides just do not hold the WoW factor or PoP for me.  Sure the image is clear, blanced, maybe too much light but its nice just not exciting.</td>', 'I have seen several similar types of images in this challenge so far.  However I have to say this one is more true photograph then some of the others.  Yet it still is just middle of the road for me.  After seeing so many of these types of images, no matter the location, the center composition mirrored sides just do not hold the WoW factor or PoP for me.  Sure the image is clear, blanced, maybe too much light but its nice just not exciting.', '2010-01-02 21:49:17.000000', NULL, 1),
(5792153, 842613, 87252, '<td valign="top">Great shot - I think a bit of careful contrast work would have improved this slightly.</td>', 'Great shot - I think a bit of careful contrast work would have improved this slightly.', '2010-01-02 21:50:36.000000', NULL, 1),
(5792155, 843130, 111808, '<td valign="top">This is beautiful in the interaction of the horses and the child. It is clear that the little boy loves the big brown horse and it is reciprocated by the animal. The white one gives him a nuzzle from behind, the expression one of gentleness and desire. This is one of those perfect moment captures defined by both the heart and the eye. Kudos to the photographer who has offered it up to be shared and enjoyed by all.</td>', 'This is beautiful in the interaction of the horses and the child. It is clear that the little boy loves the big brown horse and it is reciprocated by the animal. The white one gives him a nuzzle from behind, the expression one of gentleness and desire. This is one of those perfect moment captures defined by both the heart and the eye. Kudos to the photographer who has offered it up to be shared and enjoyed by all.', '2010-01-02 21:50:41.000000', NULL, 1),
(5792157, 841890, 16197, '<td valign="top">With this much rust I would have loved to see the processing pushed a bit to really bring it all out.  This here appears to be a snapshot, yet it was not balanced or composed very well.  The detachment of the hood of the car in the foreground is misplaced and does not make any sense to me when it appears the trailer is the subject.  For me, I would have enjoyed a nice strong low angle shot of the car in all its rust and glory or even something more dramatic with the trailer alone.  But as the two, it just does not do it for me.</td>', 'With this much rust I would have loved to see the processing pushed a bit to really bring it all out.  This here appears to be a snapshot, yet it was not balanced or composed very well.  The detachment of the hood of the car in the foreground is misplaced and does not make any sense to me when it appears the trailer is the subject.  For me, I would have enjoyed a nice strong low angle shot of the car in all its rust and glory or even something more dramatic with the trailer alone.  But as the two, it just does not do it for me.', '2010-01-02 21:51:19.000000', NULL, 1),
(5792160, 843254, 87252, '<td valign="top">Took me a second to work out the angles involved here, very clever composition.</td>', 'Took me a second to work out the angles involved here, very clever composition.', '2010-01-02 21:52:04.000000', NULL, 1),
(5792168, 841789, 87252, '<td valign="top">I think you may have just missed the focus on this, looks very cold though so perhaps frozen fingers may have been the culprit! Cool portrait.</td>', 'I think you may have just missed the focus on this, looks very cold though so perhaps frozen fingers may have been the culprit! Cool portrait.', '2010-01-02 21:54:01.000000', NULL, 1),
(5792169, 841671, 111808, '<td valign="top">This is so detailed that you can see the individual frost spikes on it and the branch. Although the leaf is largely brown and dead there still yet is a small touch of the summer green about it. Beautiful capture.</td>', 'This is so detailed that you can see the individual frost spikes on it and the branch. Although the leaf is largely brown and dead there still yet is a small touch of the summer green about it. Beautiful capture.', '2010-01-02 21:54:36.000000', NULL, 1),
(5792171, 843094, 87252, '<td valign="top">Very nice colours and DOF, you really nailed the focus.</td>', 'Very nice colours and DOF, you really nailed the focus.', '2010-01-02 21:54:50.000000', NULL, 1),
(5792173, 842970, 87252, '<td valign="top">Now THAT is the face of the next big rock and roll powerhouse.</td>', 'Now THAT is the face of the next big rock and roll powerhouse.', '2010-01-02 21:55:42.000000', NULL, 1),
(5792175, 843093, 93565, '<td valign="top">The detail in the feathers is exceptional, but there are a couple things in the composition that I''m not so sure about. The tail feather appears to be clipped a bit, and I''d like to have the breast of the gull against a background that doesn''t so nearly blend into it tone wise.</td>', 'The detail in the feathers is exceptional, but there are a couple things in the composition that I''m not so sure about. The tail feather appears to be clipped a bit, and I''d like to have the breast of the gull against a background that doesn''t so nearly blend into it tone wise.', '2010-01-02 21:56:06.000000', NULL, 1),
(5792178, 842197, 87252, '<td valign="top">Cool shot, you did well to get them so close together in the frame. Not so sure about the capitals and unnecessary punctuation in the title - but then I am an English teacher so I''m super sensitive :).</td>', 'Cool shot, you did well to get them so close together in the frame. Not so sure about the capitals and unnecessary punctuation in the title - but then I am an English teacher so I''m super sensitive :).', '2010-01-02 21:58:39.000000', NULL, 1),
(5792182, 841497, 87252, '<td valign="top">This is cool - perhaps a bit over saturated to score very high but I like it in a Martin Parr sort of way :)</td>', 'This is cool - perhaps a bit over saturated to score very high but I like it in a Martin Parr sort of way :)', '2010-01-02 22:00:43.000000', NULL, 1),
(5792187, 840538, 87252, '<td valign="top">Sweet shot and I like the soft focus. I think you should have more faith in voters to spot a candid shot - little "instructions" in the titles on how to view a photo always strike me as a bit patronising and you might actually lose points because of it. Just my 2 cents! :)</td>', 'Sweet shot and I like the soft focus. I think you should have more faith in voters to spot a candid shot - little "instructions" in the titles on how to view a photo always strike me as a bit patronising and you might actually lose points because of it. Just my 2 cents! :)', '2010-01-02 22:04:31.000000', NULL, 1),
(5792188, 843247, 87252, '<td valign="top">Cool - the processing makes them look like they''re on some distant planet somewhere. Surreal.</td>', 'Cool - the processing makes them look like they''re on some distant planet somewhere. Surreal.', '2010-01-02 22:05:39.000000', NULL, 1),
(5792189, 840158, 111808, '<td valign="top">I like the black and white portrait of this critter. Each coathair blends into a smooth yet directional pattern while the eye focus is critically sharp. He is more clearly defined by the blurred background giving an intimate look at a very quick creature not commonly still long enough to be really seen.</td>', 'I like the black and white portrait of this critter. Each coathair blends into a smooth yet directional pattern while the eye focus is critically sharp. He is more clearly defined by the blurred background giving an intimate look at a very quick creature not commonly still long enough to be really seen.', '2010-01-02 22:05:43.000000', NULL, 1),
(5792190, 839307, 16197, '<td valign="top">Fun snapshot of the nightlife in the area.  For me though it just does not hold enough interest or story for me.</td>', 'Fun snapshot of the nightlife in the area.  For me though it just does not hold enough interest or story for me.', '2010-01-02 22:06:10.000000', NULL, 1),
(5792193, 841599, 87252, '<td valign="top">Nice snow streaks, perhaps a bit noisy though.</td>', 'Nice snow streaks, perhaps a bit noisy though.', '2010-01-02 22:07:29.000000', NULL, 1),
(5792194, 843252, 16197, '<td valign="top">The dreamy processing of the image for me does not work.  I am sure many people enjoy it but for me it seems the photography loses its essence and becomes more of a digital illustration then a photography.  It appears too unreal for me.</td>', 'The dreamy processing of the image for me does not work.  I am sure many people enjoy it but for me it seems the photography loses its essence and becomes more of a digital illustration then a photography.  It appears too unreal for me.', '2010-01-02 22:07:43.000000', NULL, 1),
