(5793422, 841561, 10785, '<td valign="top">Did I see this same cat in the Love Challenge? If so, then here you really nailed the depth of field. I think this is an awesome portrait.</td>', 'Did I see this same cat in the Love Challenge? If so, then here you really nailed the depth of field. I think this is an awesome portrait.', '2010-01-03 16:41:32.000000', NULL, 1),
(5793426, 841456, 10785, '<td valign="top">Beautiful colors and wonderful composition. One improvement if possible would have been to get closer to avoid the rope at the bottom of the shot.</td>', 'Beautiful colors and wonderful composition. One improvement if possible would have been to get closer to avoid the rope at the bottom of the shot.', '2010-01-03 16:43:14.000000', NULL, 1),
