(5793792, 842946, 108384, '<td valign="top">Oh my God....that can''t be real.  If I could vote, this would be an undisputed 10.</td>', 'Oh my God....that can''t be real.  If I could vote, this would be an undisputed 10.', '2010-01-03 20:03:27.000000', NULL, 1),
(5793797, 842203, 108384, '<td valign="top">Outstanding perspective and use of the fisheye.</td>', 'Outstanding perspective and use of the fisheye.', '2010-01-03 20:05:19.000000', NULL, 1),
(5793801, 842838, 108384, '<td valign="top">Absolutely brilliant.  I know this probably won''t go over well with the general public, but I adore your style.</td>', 'Absolutely brilliant.  I know this probably won''t go over well with the general public, but I adore your style.', '2010-01-03 20:06:13.000000', NULL, 1),
(5793815, 840924, 10785, '<td valign="top">Wonderful perspective. I think the composition might have been stronger if you could have taken a few steps to the left and rotated yourself looking more straight at the building. I love the twinkle of the lights on the tree.</td>', 'Wonderful perspective. I think the composition might have been stronger if you could have taken a few steps to the left and rotated yourself looking more straight at the building. I love the twinkle of the lights on the tree.', '2010-01-03 20:11:15.000000', NULL, 1),
(5793824, 843274, 76335, '<td valign="top">Too out of focus.</td>', 'Too out of focus.', '2010-01-03 20:19:09.000000', NULL, 1),
(5793825, 843002, 10785, '<td valign="top">This is a good landscape. You''ve got the rocks foreground, lights reflected at midrange and bridge and sky in the background all in good focus with excellent color. The only downfall with this is that all the leading lines lead you out of the frame. The wires and the line of the bridge all lead the eye to the top left corner where there is nothing interesting to look at.</td>', 'This is a good landscape. You''ve got the rocks foreground, lights reflected at midrange and bridge and sky in the background all in good focus with excellent color. The only downfall with this is that all the leading lines lead you out of the frame. The wires and the line of the bridge all lead the eye to the top left corner where there is nothing interesting to look at.', '2010-01-03 20:19:33.000000', NULL, 1),
(5793828, 843283, 76335, '<td valign="top">Effectively framed to show off all sorts of wonderful textures and chaotic fractal-like patterns.</td>', 'Effectively framed to show off all sorts of wonderful textures and chaotic fractal-like patterns.', '2010-01-03 20:22:03.000000', NULL, 1),
