(5795629, 839717, 30049, '<td valign="top">This place looks vaguely familiar.  That''s a big pile of ice!</td>', 'This place looks vaguely familiar.  That''s a big pile of ice!', '2010-01-04 16:26:24.000000', NULL, 1),
(5795632, 843223, 16197, '<td valign="top">Kinda cute image.  Though The top unbalances the bottom and distracts my eye.  I see with your title your concept, however for me it did not work well to balance the frame.  Perhaps a landscape view would have been more beneficial.</td>', 'Kinda cute image.  Though The top unbalances the bottom and distracts my eye.  I see with your title your concept, however for me it did not work well to balance the frame.  Perhaps a landscape view would have been more beneficial.', '2010-01-04 16:28:55.000000', NULL, 1),
(5795636, 843002, 16197, '<td valign="top">This is kinda nice.  The colours of the green on the supports and the white on the suspensions are nice.  However the fire orange and electric poles create a strong distraction.  I am on the fence about the foreground items, Though I think if it was cropped off to show only the bridge and reflection it would have stood a lot stronger.</td>', 'This is kinda nice.  The colours of the green on the supports and the white on the suspensions are nice.  However the fire orange and electric poles create a strong distraction.  I am on the fence about the foreground items, Though I think if it was cropped off to show only the bridge and reflection it would have stood a lot stronger.', '2010-01-04 16:30:30.000000', NULL, 1),
(5795640, 843310, 16197, '<td valign="top">This is interesting though the center composition does nothing for me.  Yet I read your title and notice the gentleman walking.  This image is more about the stature/sculpture then the guy walking.  Overall it is an ok snapshot but just does nothing for me.</td>', 'This is interesting though the center composition does nothing for me.  Yet I read your title and notice the gentleman walking.  This image is more about the stature/sculpture then the guy walking.  Overall it is an ok snapshot but just does nothing for me.', '2010-01-04 16:31:36.000000', NULL, 1),
(5795643, 843013, 16197, '<td valign="top">The old-style of this image is slightly appealing.  The composition and contrasts are ok, though perhaps could have been pushed a bit more.</td>', 'The old-style of this image is slightly appealing.  The composition and contrasts are ok, though perhaps could have been pushed a bit more.', '2010-01-04 16:32:27.000000', NULL, 1),
(5795647, 843104, 16197, '<td valign="top">Nice idea.  I am surprised how much weight is being supported.  The direct flash hinders the possibility of vivid colour and clarity.    I wonder if this was brought in a lot more, perhaps focusing more on the drop and cropping most the rest of the snow off and pushing the sat how it would have looked.</td>', 'Nice idea.  I am surprised how much weight is being supported.  The direct flash hinders the possibility of vivid colour and clarity.    I wonder if this was brought in a lot more, perhaps focusing more on the drop and cropping most the rest of the snow off and pushing the sat how it would have looked.', '2010-01-04 16:33:53.000000', NULL, 1),
(5795651, 843273, 16197, '<td valign="top">With this much texture I would have loved to see a sharper focal plane.  Also I would have liked a bit more life with the colours and possibly a different angle so not to catch only the profile of the back critter.  Overall it is nice, it is cute, but it is not for me.</td>', 'With this much texture I would have loved to see a sharper focal plane.  Also I would have liked a bit more life with the colours and possibly a different angle so not to catch only the profile of the back critter.  Overall it is nice, it is cute, but it is not for me.', '2010-01-04 16:37:55.000000', NULL, 1),
(5795652, 843246, 16197, '<td valign="top">There is huge possibility here for face slapping colours.  However they are not here, and I feel this image is left feeling flat and cold.</td>', 'There is huge possibility here for face slapping colours.  However they are not here, and I feel this image is left feeling flat and cold.', '2010-01-04 16:38:38.000000', NULL, 1),
(5795660, 843109, 16197, '<td valign="top">This is a cute portrait with the classic editing style and expression I am sure the photographer and parent/s are extremely happy.  However me, being an outside viewer with no emotional attachment I would say it is not a strong enough piece.  it is nice, don''t get me wrong the vinaigrette and radial blur are nice for this type of image and the forward flash even works.  Just for me it is not enough.</td>', 'This is a cute portrait with the classic editing style and expression I am sure the photographer and parent/s are extremely happy.  However me, being an outside viewer with no emotional attachment I would say it is not a strong enough piece.  it is nice, don''t get me wrong the vinaigrette and radial blur are nice for this type of image and the forward flash even works.  Just for me it is not enough.', '2010-01-04 16:44:01.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5795662, 843304, 16197, '<td valign="top">Nice simple image.  A bit noisy for me.  Also I am lose to where the in between is?  There appears to be smudge marks or something as well.  Every peculiar.</td>', 'Nice simple image.  A bit noisy for me.  Also I am lose to where the in between is?  There appears to be smudge marks or something as well.  Every peculiar.', '2010-01-04 16:44:56.000000', NULL, 1),
(5795664, 843209, 16197, '<td valign="top">Classic style of image, though for me it is way to dark.  The whites should be much lighter and the eyes should also be a bit lighter as to see them more.  I can see slight crescents of eye now but it is not enough it can easily appear to be two lumps of coal.</td>', 'Classic style of image, though for me it is way to dark.  The whites should be much lighter and the eyes should also be a bit lighter as to see them more.  I can see slight crescents of eye now but it is not enough it can easily appear to be two lumps of coal.', '2010-01-04 16:46:07.000000', NULL, 1),
(5795669, 843010, 16197, '<td valign="top">I have looked at this image a few times.  I have to say this piece of ''digital art'' is nice, its cute its festive but it is not for me.  I find the plastic figures appear over processes with too many effects on them.  They stopped looking like a photograph of plastic horses and started looking like a digital illustration.  Now if I am mistaken and these are actually real horses (which I have no doubt they are not) then you really went way to far in post for a photography challenge.  It just does not do it.</td>', 'I have looked at this image a few times.  I have to say this piece of ''digital art'' is nice, its cute its festive but it is not for me.  I find the plastic figures appear over processes with too many effects on them.  They stopped looking like a photograph of plastic horses and started looking like a digital illustration.  Now if I am mistaken and these are actually real horses (which I have no doubt they are not) then you really went way to far in post for a photography challenge.  It just does not do it.', '2010-01-04 16:48:26.000000', NULL, 1),
(5795673, 842818, 16197, '<td valign="top">I do not know exactly how these critters actually appear but this one appears overly smoothed which creates a fake like feel for me.  I think there could be huge possibles and wow and bang and pop here.  But with the overly smoothed image it takes out all the texture all the detail all the personality I would have enjoyed seeing.</td>', 'I do not know exactly how these critters actually appear but this one appears overly smoothed which creates a fake like feel for me.  I think there could be huge possibles and wow and bang and pop here.  But with the overly smoothed image it takes out all the texture all the detail all the personality I would have enjoyed seeing.', '2010-01-04 16:49:57.000000', NULL, 1),
(5795675, 842875, 16197, '<td valign="top">This is a nice find.  Makes me think of old rubberband balls.  For me though I would have liked to see the background colour toned down a bit and the nest pushed up as hard as it can go.  There is such a life hidden inside there yet with these dull muted colours it is hidden.</td>', 'This is a nice find.  Makes me think of old rubberband balls.  For me though I would have liked to see the background colour toned down a bit and the nest pushed up as hard as it can go.  There is such a life hidden inside there yet with these dull muted colours it is hidden.', '2010-01-04 16:50:51.000000', NULL, 1),
(5795677, 842964, 16197, '<td valign="top">This is a nice find.  The snapshot is ok but there is a huge amount of character and personality lost.  I see the old train with the boarded windows and peeling paint and I am sure there is rust there, yet it is all hidden in a flat black/white image.  I would really have enjoyed seeing a bit more contrast in this as well as push on the details to stand out.  I see there is a little push but it muddles the finer detail and does not offer enough depth for the larger.</td>', 'This is a nice find.  The snapshot is ok but there is a huge amount of character and personality lost.  I see the old train with the boarded windows and peeling paint and I am sure there is rust there, yet it is all hidden in a flat black/white image.  I would really have enjoyed seeing a bit more contrast in this as well as push on the details to stand out.  I see there is a little push but it muddles the finer detail and does not offer enough depth for the larger.', '2010-01-04 16:52:37.000000', NULL, 1),
(5795679, 843173, 16197, '<td valign="top">Interesting concept I give you that.  The near center composition with distorted perspective is also interesting but not enough to really want me to continue looking.  It appears we can see all we want to within a brief second of viewing. There is no real interest or activity going on that warrants the eye to stay.</td>', 'Interesting concept I give you that.  The near center composition with distorted perspective is also interesting but not enough to really want me to continue looking.  It appears we can see all we want to within a brief second of viewing. There is no real interest or activity going on that warrants the eye to stay.', '2010-01-04 16:53:53.000000', NULL, 1),
(5795681, 843296, 16197, '<td valign="top">This type of processing is really not good in my opinion.  The blurred ''dreamy'' style for me just distracts and ignores the elements of the piece and does no justice to the depths and contrasts and character of the subjects.</td>', 'This type of processing is really not good in my opinion.  The blurred ''dreamy'' style for me just distracts and ignores the elements of the piece and does no justice to the depths and contrasts and character of the subjects.', '2010-01-04 16:54:53.000000', NULL, 1),
(5795682, 843300, 16197, '<td valign="top">Nice cute portrait.  Focal clarity is nice, contrasts are ok, could be pushed a bit brighter on the skin tones.  Overall its a nice portrait just not enough for me for this challenge.</td>', 'Nice cute portrait.  Focal clarity is nice, contrasts are ok, could be pushed a bit brighter on the skin tones.  Overall its a nice portrait just not enough for me for this challenge.', '2010-01-04 16:55:33.000000', NULL, 1),
(5795684, 842838, 16197, '<td valign="top">I can appreciate the art in this image.  Or the joke, whichever it may be.  Though it does not offer me enough, does not push me enough to really give it a second look.  I would hope for something more, something of a statement.  Your title also offers me nothing to go on.</td>', 'I can appreciate the art in this image.  Or the joke, whichever it may be.  Though it does not offer me enough, does not push me enough to really give it a second look.  I would hope for something more, something of a statement.  Your title also offers me nothing to go on.', '2010-01-04 16:56:43.000000', NULL, 1),
(5795686, 843188, 16197, '<td valign="top">Classic type of image.  Nice pastel colours, though everything appears overly smoothed.  Just not enough for me.  It is nice and all.  But just not there, just no wow, pop or bang.</td>', 'Classic type of image.  Nice pastel colours, though everything appears overly smoothed.  Just not enough for me.  It is nice and all.  But just not there, just no wow, pop or bang.', '2010-01-04 16:57:35.000000', NULL, 1),
(5795689, 842985, 16197, '<td valign="top">Front perspective with distorted perception.   I would have liked that adjusted so it was more square, specially with a straight on view.  It is almost an interesting building it appears it might have some character hidden there but it does not give me enough brightness or colour.  The depth of texture from the roof to the brick wall should be screaming at me and it does not.</td>', 'Front perspective with distorted perception.   I would have liked that adjusted so it was more square, specially with a straight on view.  It is almost an interesting building it appears it might have some character hidden there but it does not give me enough brightness or colour.  The depth of texture from the roof to the brick wall should be screaming at me and it does not.', '2010-01-04 16:59:43.000000', NULL, 1),
(5795692, 843120, 16197, '<td valign="top">Interesting find.  Though direct flash really does it no justice as does the straight on view.  I would have liked a more creative perspective or camera angle to these trees.  Also if possible off-camera lighting.  Though I know that is not always an option.</td>', 'Interesting find.  Though direct flash really does it no justice as does the straight on view.  I would have liked a more creative perspective or camera angle to these trees.  Also if possible off-camera lighting.  Though I know that is not always an option.', '2010-01-04 17:00:43.000000', NULL, 1),
(5795697, 843215, 16197, '<td valign="top">This could be a really powerful view.  Though the overly dark and flat image here does not come close.  I would have liked something very strong with contrast.  Something that is clear and solid.  A piece that just screams at me.</td>', 'This could be a really powerful view.  Though the overly dark and flat image here does not come close.  I would have liked something very strong with contrast.  Something that is clear and solid.  A piece that just screams at me.', '2010-01-04 17:02:33.000000', NULL, 1),
(5795699, 842926, 16197, '<td valign="top">Cute dog image.  Though a snapshot for sure, and I am positive the owner is quite happy with it and that is what matters most.</td>', 'Cute dog image.  Though a snapshot for sure, and I am positive the owner is quite happy with it and that is what matters most.', '2010-01-04 17:03:19.000000', NULL, 1),
(5795704, 843283, 16197, '<td valign="top">I would have said Hopelessness, it just flows better.  But beside the point, I find this image extremely busy though there are blurred/ghosted areas that really cause my main distraction.  If there would have been a way to have the light come from inside instead of outside I think it would have been a much stronger piece.  However as it is, it is just too busy for me with no clear clarity of view.</td>', 'I would have said Hopelessness, it just flows better.  But beside the point, I find this image extremely busy though there are blurred/ghosted areas that really cause my main distraction.  If there would have been a way to have the light come from inside instead of outside I think it would have been a much stronger piece.  However as it is, it is just too busy for me with no clear clarity of view.', '2010-01-04 17:05:16.000000', NULL, 1),
(5795712, 842970, 16197, '<td valign="top">Nice fun snapshot of the Kiddo.  The look of determination is nice, and the blurred stick offers action/motion which may hint that this was not too posed.  The wall directly behind him is a distraction I would have liked to see it pushed back a few feet.  Also whatever the white box is behind him catches my eye.  For me there just does not seem to be strong enough sense of rockstar which I would have liked to see more of.  Perhaps the center composition/framing is where a lot is lost.</td>', 'Nice fun snapshot of the Kiddo.  The look of determination is nice, and the blurred stick offers action/motion which may hint that this was not too posed.  The wall directly behind him is a distraction I would have liked to see it pushed back a few feet.  Also whatever the white box is behind him catches my eye.  For me there just does not seem to be strong enough sense of rockstar which I would have liked to see more of.  Perhaps the center composition/framing is where a lot is lost.', '2010-01-04 17:11:54.000000', NULL, 1),
(5795717, 842991, 16197, '<td valign="top">Interesting concept, fun perspective, though not pushed enough.  There is just something missing here and that angular piece on the view left is a distraction for me. Moreso then the one on the right.  Also I think I would have liked a bit more concept if the camera was moved a step or two to the viewer left.  To bring in more of the vertical ascension aspect with the windows.</td>', 'Interesting concept, fun perspective, though not pushed enough.  There is just something missing here and that angular piece on the view left is a distraction for me. Moreso then the one on the right.  Also I think I would have liked a bit more concept if the camera was moved a step or two to the viewer left.  To bring in more of the vertical ascension aspect with the windows.', '2010-01-04 17:13:31.000000', NULL, 1),
(5795721, 843091, 16197, '<td valign="top">Cute image, Im sure I have one quite similar to this one somewhere.  However I would have hoped it''s nose to be within the focal plane as well as it''s eyes.  I am sure this is a winner with the owner/photographer, just not with me.</td>', 'Cute image, Im sure I have one quite similar to this one somewhere.  However I would have hoped it''s nose to be within the focal plane as well as it''s eyes.  I am sure this is a winner with the owner/photographer, just not with me.', '2010-01-04 17:14:32.000000', NULL, 1),
(5795724, 843229, 16197, '<td valign="top">Nice idea, though first thing I saw was James Bond walking out into the frame.  For me, I like the creative concept here, but it is not pushed enough for me.  Perhaps if it was not solid green with blown out spots?  I think a bit more clarity would have gone a long ways in increase the vote level of this piece.</td>', 'Nice idea, though first thing I saw was James Bond walking out into the frame.  For me, I like the creative concept here, but it is not pushed enough for me.  Perhaps if it was not solid green with blown out spots?  I think a bit more clarity would have gone a long ways in increase the vote level of this piece.', '2010-01-04 17:16:44.000000', NULL, 1),
(5795727, 842937, 93565, '<td valign="top">I like this one quite a bit. Nice, dynamic sky, with a wide range of luminance (yet no clipping). Additionally, the bright colors accent things well. I like how you have captured the dichotomy of the weather, illustrating not only the turbulent stormy type, but also the calm sunset people generally associate with the beach.</td>', 'I like this one quite a bit. Nice, dynamic sky, with a wide range of luminance (yet no clipping). Additionally, the bright colors accent things well. I like how you have captured the dichotomy of the weather, illustrating not only the turbulent stormy type, but also the calm sunset people generally associate with the beach.', '2010-01-04 17:18:03.000000', NULL, 1),
(5795728, 841062, 93565, '<td valign="top">I''ve never actually tried smoke trails before, but rumor has it they can be a bit frustrating. This is an alright shot, but it doesn''t scream anything to me, it fails to connect on some level, which I think is important. Things seem a smidge grainy but that could just be me.</td>', 'I''ve never actually tried smoke trails before, but rumor has it they can be a bit frustrating. This is an alright shot, but it doesn''t scream anything to me, it fails to connect on some level, which I think is important. Things seem a smidge grainy but that could just be me.', '2010-01-04 17:18:11.000000', NULL, 1),
(5795729, 842941, 16197, '<td valign="top">Cute image of the cat.  The eye colour is nice, but it nearly appears only the one is in focus.  It also appears that the focal range is only the viewer right of the cats face behind muzzle.  For me I would have liked a lot more focal range of this piece as well as a bit more brightness in the lighter hair.  It appears old and dirty and grungy the way it is here with the dark muted colour.</td>', 'Cute image of the cat.  The eye colour is nice, but it nearly appears only the one is in focus.  It also appears that the focal range is only the viewer right of the cats face behind muzzle.  For me I would have liked a lot more focal range of this piece as well as a bit more brightness in the lighter hair.  It appears old and dirty and grungy the way it is here with the dark muted colour.', '2010-01-04 17:18:26.000000', NULL, 1),
(5795731, 842879, 16197, '<td valign="top">With these types of images I think since there has been so many they now need to be absolute perfection.  But yet, how can one have perfection if the perception of perfection is so widely varied between viewers?  For me, it is ok.  Nothing extraordinary or special.  Clarity of center is nice.  Colour is bland.  I am sure it has commercial potential but just does nothing for me.</td>', 'With these types of images I think since there has been so many they now need to be absolute perfection.  But yet, how can one have perfection if the perception of perfection is so widely varied between viewers?  For me, it is ok.  Nothing extraordinary or special.  Clarity of center is nice.  Colour is bland.  I am sure it has commercial potential but just does nothing for me.', '2010-01-04 17:20:12.000000', NULL, 1),
(5795733, 843351, 93565, '<td valign="top">Perhaps it''s just me, but it almost seems as though I can see a slight wrinkle in the background, just to the right of the subject''s eye. Hair is a tad disheveled, and some might consider cloning out some of the stray hairs, but I think they add some character and life to the portrait. What kind of baby has immaculately prepared hair, anyway? Good expression and detail/focus. Eyes have good color, but might use a small pop to bring them out a little bit more, but things are still good how they are. Good portrait.</td>', 'Perhaps it''s just me, but it almost seems as though I can see a slight wrinkle in the background, just to the right of the subject''s eye. Hair is a tad disheveled, and some might consider cloning out some of the stray hairs, but I think they add some character and life to the portrait. What kind of baby has immaculately prepared hair, anyway? Good expression and detail/focus. Eyes have good color, but might use a small pop to bring them out a little bit more, but things are still good how they are. Good portrait.', '2010-01-04 17:21:34.000000', NULL, 1),
(5795737, 842879, 93565, '<td valign="top">The infamous water drop :)<br/>You might get hit hard for doing one of the cliche''s of DPC, but your approach is nice in that it keeps things simple. To nitpick, the top drop doesn''t seem as sharply focused as the other two. The line of three drops is very nice, and a departure from the usual one or two or strange water shape. Nice take on a DPC classic subject; you''ve executed well.</td>', 'The infamous water drop :)You might get hit hard for doing one of the cliche''s of DPC, but your approach is nice in that it keeps things simple. To nitpick, the top drop doesn''t seem as sharply focused as the other two. The line of three drops is very nice, and a departure from the usual one or two or strange water shape. Nice take on a DPC classic subject; you''ve executed well.', '2010-01-04 17:23:47.000000', NULL, 1),
(5795738, 841537, 93565, '<td valign="top">Excellent pan. The details on the shifter cart and the driver are excellent, and the rest is given more than enough blur to imply some speed. Nice job.</td>', 'Excellent pan. The details on the shifter cart and the driver are excellent, and the rest is given more than enough blur to imply some speed. Nice job.', '2010-01-04 17:23:50.000000', NULL, 1),
(5795743, 842917, 93565, '<td valign="top">This shot is offset just a tiny bit, a bit small enough to make it feel almost accidental or awkward. I''m not a fan of the building on the left peaking into the frame either, and the vine in the front is rather bright, which draws me away from your focal point, the cathedral. For this, I would have preferred a more up close and personal shot, to emphasize the size and menacing edifice.</td>', 'This shot is offset just a tiny bit, a bit small enough to make it feel almost accidental or awkward. I''m not a fan of the building on the left peaking into the frame either, and the vine in the front is rather bright, which draws me away from your focal point, the cathedral. For this, I would have preferred a more up close and personal shot, to emphasize the size and menacing edifice.', '2010-01-04 17:28:50.000000', NULL, 1),
(5795744, 841889, 93565, '<td valign="top">Nice skin tones and especially great job on the expressions. Too often portraits look canned and forced, but this is very natural, so your candid approach succeeded. The blown collar is a little distracting, but it''s minor. I think I agree with cutting off his hat, it seems to me that she might look really weird with only a little bit of her neck showing.</td>', 'Nice skin tones and especially great job on the expressions. Too often portraits look canned and forced, but this is very natural, so your candid approach succeeded. The blown collar is a little distracting, but it''s minor. I think I agree with cutting off his hat, it seems to me that she might look really weird with only a little bit of her neck showing.', '2010-01-04 17:28:53.000000', NULL, 1),
(5795745, 841890, 93565, '<td valign="top">I like the texture on the Rambler''s hood. It''s also nice that all of the tones are rather drab... lends to the "End of an Era" idea. What might have really added to this is if you waited for a new car to drive by in the background, especially if your shutter was longer and there was motion blur on the newer car. I would have liked that quite a bit, continuing the theme by showing the viewer these static objects being left behind by the future.</td>', 'I like the texture on the Rambler''s hood. It''s also nice that all of the tones are rather drab... lends to the "End of an Era" idea. What might have really added to this is if you waited for a new car to drive by in the background, especially if your shutter was longer and there was motion blur on the newer car. I would have liked that quite a bit, continuing the theme by showing the viewer these static objects being left behind by the future.', '2010-01-04 17:28:56.000000', NULL, 1),
(5795746, 841880, 93565, '<td valign="top">This is an interesting capture, almost like a prelude to the night. She''s obviously dressed up and ready to go out, or maybe she''s at a party? Good job making the viewer wonder what she''s doing here, and abstracting a moment from her night.</td>', 'This is an interesting capture, almost like a prelude to the night. She''s obviously dressed up and ready to go out, or maybe she''s at a party? Good job making the viewer wonder what she''s doing here, and abstracting a moment from her night.', '2010-01-04 17:28:59.000000', NULL, 1),
(5795772, 843258, 93565, '<td valign="top">This has an interesting solemn and calm atmosphere about it. The single, dark horse eye serves as a nice focal point, and I like the few coarse hairs that are draped across. I like this, but I think it would fare much better in a challenge more associated with the subject matter than a FS, which demands "wow" factor to score high. Great use of DoF, and I think you''ve succeeded in this photo.</td>', 'This has an interesting solemn and calm atmosphere about it. The single, dark horse eye serves as a nice focal point, and I like the few coarse hairs that are draped across. I like this, but I think it would fare much better in a challenge more associated with the subject matter than a FS, which demands "wow" factor to score high. Great use of DoF, and I think you''ve succeeded in this photo.', '2010-01-04 17:39:13.000000', NULL, 1),
(5795806, 843318, 93565, '<td valign="top">Interesting subject matter, that''s for sure. I gotta ask, how the hell are those powered? Was the cord cloned out? Anyway, you did a good job choosing an interesting photo of Christmas lights, and it seems you let your ambient drop down to a low enough level, but not sure if you set your WB to tungsten on this, as the glow seems a bit warm below the tree.</td>', 'Interesting subject matter, that''s for sure. I gotta ask, how the hell are those powered? Was the cord cloned out? Anyway, you did a good job choosing an interesting photo of Christmas lights, and it seems you let your ambient drop down to a low enough level, but not sure if you set your WB to tungsten on this, as the glow seems a bit warm below the tree.', '2010-01-04 17:55:39.000000', NULL, 1),
(5795807, 841950, 93565, '<td valign="top">I really like this shot. The fact that the person has a big fluffy mane of hair really makes this shot intriguing, as well as the expression on their face. Very cool.</td>', 'I really like this shot. The fact that the person has a big fluffy mane of hair really makes this shot intriguing, as well as the expression on their face. Very cool.', '2010-01-04 17:55:42.000000', NULL, 1),
(5795810, 843023, 16197, '<td valign="top">This is a nicely composed image.  I enjoy the various lines of the fence around the tree.  I also enjoy the various levels of contrast between the elements.  Looking at this piece again I will bump the score slightly from average to above.  But for me it just is not enough to really blow me out of my sox.</td>', 'This is a nicely composed image.  I enjoy the various lines of the fence around the tree.  I also enjoy the various levels of contrast between the elements.  Looking at this piece again I will bump the score slightly from average to above.  But for me it just is not enough to really blow me out of my sox.', '2010-01-04 17:57:35.000000', NULL, 1),
(5795811, 842996, 93565, '<td valign="top">Very cool photo. I''m torn between asking for more DoF to see a bit more of the legs or keeping it how it is so the web stays out of focus. Either way, nice shot. You background is even (mostly) an agreeable color.</td>', 'Very cool photo. I''m torn between asking for more DoF to see a bit more of the legs or keeping it how it is so the web stays out of focus. Either way, nice shot. You background is even (mostly) an agreeable color.', '2010-01-04 17:57:37.000000', NULL, 1),
(5795812, 843257, 16197, '<td valign="top">I enjoy the creative nature of this image.  However for me it is lacking something to really make me stand up to attention.  It is fun but perhaps it does not hold enough clarity for me.</td>', 'I enjoy the creative nature of this image.  However for me it is lacking something to really make me stand up to attention.  It is fun but perhaps it does not hold enough clarity for me.', '2010-01-04 17:58:19.000000', NULL, 1),
(5795813, 840494, 93565, '<td valign="top">Lots of nice textures here, and the warm contrasts very nicely with the cool, which is probably the strongest part of this photo. The line of poles or whatever going off into the distance is interesting too. It''s a bummer you got that tiny bit of blown highlight on the left, but it''s only a slight distraction.</td>', 'Lots of nice textures here, and the warm contrasts very nicely with the cool, which is probably the strongest part of this photo. The line of poles or whatever going off into the distance is interesting too. It''s a bummer you got that tiny bit of blown highlight on the left, but it''s only a slight distraction.', '2010-01-04 17:59:55.000000', NULL, 1),
(5795822, 843094, 93565, '<td valign="top">Great portrait. Nice job making the eyes pop- they add a nice intensity to the pose. I''d like this quite a bit more if the bokeh weren''t distracting... perhaps its the lens that you''ve used, or the aperture or the distance to the trees in the background... not sure which. Either way, I''d like the branches a bit more blurred out. Maybe also consider composing the shot such that the line where the snow becomes trees is not included in the frame. Elevate the POV to include only snow or lower it to include only trees so that there isn''t that strong line between light and dark in the background.</td>', 'Great portrait. Nice job making the eyes pop- they add a nice intensity to the pose. I''d like this quite a bit more if the bokeh weren''t distracting... perhaps its the lens that you''ve used, or the aperture or the distance to the trees in the background... not sure which. Either way, I''d like the branches a bit more blurred out. Maybe also consider composing the shot such that the line where the snow becomes trees is not included in the frame. Elevate the POV to include only snow or lower it to include only trees so that there isn''t that strong line between light and dark in the background.', '2010-01-04 18:07:42.000000', NULL, 1),
(5795826, 843352, 16197, '<td valign="top">Cute image, proud parents and photographer I am sure.  I enjoy the snowfall background.  That being said, for me it is just another nice portrait of a kid.  No wow or pop factor for me.</td>', 'Cute image, proud parents and photographer I am sure.  I enjoy the snowfall background.  That being said, for me it is just another nice portrait of a kid.  No wow or pop factor for me.', '2010-01-04 18:11:56.000000', NULL, 1),
(5795828, 841909, 93565, '<td valign="top">Nice purple tinge to this flower. Your framing is interesting too, not too often I see somebody go with a close crop on a flower. A bit more DoF might help this, but it''s nice as is.</td>', 'Nice purple tinge to this flower. Your framing is interesting too, not too often I see somebody go with a close crop on a flower. A bit more DoF might help this, but it''s nice as is.', '2010-01-04 18:13:09.000000', NULL, 1),
(5795831, 843115, 93565, '<td valign="top">Great leading lines. Really pulls the viewer into the distance. Your border works pretty well with this too.</td>', 'Great leading lines. Really pulls the viewer into the distance. Your border works pretty well with this too.', '2010-01-04 18:14:32.000000', NULL, 1),
(5795834, 842210, 93565, '<td valign="top">Too bad you missed the Contre Jour challenge; this would be well suited for that. I kinda like the lens flare you got going on here too, as well as the obliteration of everything but the barn. Interestingly, it seems almost in direct contrast to the barn''s place in the world, wherein small farms and the associated are being obliterated by the changing times and giant agri-business.</td>', 'Too bad you missed the Contre Jour challenge; this would be well suited for that. I kinda like the lens flare you got going on here too, as well as the obliteration of everything but the barn. Interestingly, it seems almost in direct contrast to the barn''s place in the world, wherein small farms and the associated are being obliterated by the changing times and giant agri-business.', '2010-01-04 18:17:17.000000', NULL, 1),
(5795836, 840924, 93565, '<td valign="top">This is an excellent example of how to capture the essence and magnitude of a large building. I like how it is peeking from behind the tree, as if to hide  I just wish the tree weren''t clipped at the top. Beyond that, magnificent photo.</td>', 'This is an excellent example of how to capture the essence and magnitude of a large building. I like how it is peeking from behind the tree, as if to hide  I just wish the tree weren''t clipped at the top. Beyond that, magnificent photo.', '2010-01-04 18:19:48.000000', NULL, 1),
(5795849, 843118, 16197, '<td valign="top">To bad the Kiddo is look''n at the camera.  Otherwise I do enjoy the clarity and perspective of this image.  The colours may be a bit orange for my taste however.</td>', 'To bad the Kiddo is look''n at the camera.  Otherwise I do enjoy the clarity and perspective of this image.  The colours may be a bit orange for my taste however.', '2010-01-04 18:23:48.000000', NULL, 1),
(5795851, 842012, 93565, '<td valign="top">Cool iguana pic. Great detail throughout nearly the whole image (ever so slight loss of focus below the chin and on the snout). The saliva-cicle adds to the pose I think. Nice framing.</td>', 'Cool iguana pic. Great detail throughout nearly the whole image (ever so slight loss of focus below the chin and on the snout). The saliva-cicle adds to the pose I think. Nice framing.', '2010-01-04 18:24:24.000000', NULL, 1),
(5795853, 842852, 16197, '<td valign="top">I enjoy the elements here.  Though for me there is not enough pop in them to really stand out.  Also for me it feels a bit muted dark, which dulls the colours.</td>', 'I enjoy the elements here.  Though for me there is not enough pop in them to really stand out.  Also for me it feels a bit muted dark, which dulls the colours.', '2010-01-04 18:24:56.000000', NULL, 1),
(5795855, 843351, 16197, '<td valign="top">Cute Kiddo portrait.  Im sure the parents and photographer are quite happy with the image.  The clarity and lighting is nice.  However for me it is just another portrait and for me it just does not do it for me in this challenge.</td>', 'Cute Kiddo portrait.  Im sure the parents and photographer are quite happy with the image.  The clarity and lighting is nice.  However for me it is just another portrait and for me it just does not do it for me in this challenge.', '2010-01-04 18:25:50.000000', NULL, 1),
(5795858, 843169, 16197, '<td valign="top">I enjoy the glow of the dark red.  However the rest of the image is blown out in the area around the sun.  For me it is not enough, it is kinda boring and holds no real interest for me.</td>', 'I enjoy the glow of the dark red.  However the rest of the image is blown out in the area around the sun.  For me it is not enough, it is kinda boring and holds no real interest for me.', '2010-01-04 18:28:18.000000', NULL, 1),
(5795859, 843174, 16197, '<td valign="top">This is a fun image, very creative perspective.  Though for me the inner image is a bit noisy and I would have enjoyed much more clarity.  However, after looking at this a second time I will bump the score for the creativity.</td>', 'This is a fun image, very creative perspective.  Though for me the inner image is a bit noisy and I would have enjoyed much more clarity.  However, after looking at this a second time I will bump the score for the creativity.', '2010-01-04 18:30:15.000000', NULL, 1),
(5795860, 843166, 16197, '<td valign="top">Nice clean portrait.  Vivid eyes and hair.  The clarity is nice, focal range works.  Just for me it is another nice portrait.  I would hope for something a bit more to really blow me away.</td>', 'Nice clean portrait.  Vivid eyes and hair.  The clarity is nice, focal range works.  Just for me it is another nice portrait.  I would hope for something a bit more to really blow me away.', '2010-01-04 18:30:57.000000', NULL, 1),
(5795864, 841297, 93565, '<td valign="top">The large building spire in the background really detracts from the "natural-ness" (for lack of a better term) of this shot. You have the wood building, whose tones are complimented by the changing leaves, and then there''s that random chunk of steel. Also, there''s some noise in the upper right sky, could use some noise reduction on the blue channel.</td>', 'The large building spire in the background really detracts from the "natural-ness" (for lack of a better term) of this shot. You have the wood building, whose tones are complimented by the changing leaves, and then there''s that random chunk of steel. Also, there''s some noise in the upper right sky, could use some noise reduction on the blue channel.', '2010-01-04 18:34:49.000000', NULL, 1),
(5795868, 842852, 93565, '<td valign="top">Interesting scene, but I think your sensor wasn''t quite up to capturing the dynamic range of this particular scene. The right sky is blown out a good deal. Your choice of location is good though. The sandstone''s layers are neat and the "sponge" textured rocks in the center are cool too.</td>', 'Interesting scene, but I think your sensor wasn''t quite up to capturing the dynamic range of this particular scene. The right sky is blown out a good deal. Your choice of location is good though. The sandstone''s layers are neat and the "sponge" textured rocks in the center are cool too.', '2010-01-04 18:36:28.000000', NULL, 1),
(5795870, 842206, 16197, '<td valign="top">A fairly clean snapshot portrait.  The square crop adds a bit more interest but with the hair fading into the background it distracts.  The contrast is fairly nice between the jacket and skintones along with the hint of colour in the shirt.  Overall it is a nice image, just does not have the wow factor for me.</td>', 'A fairly clean snapshot portrait.  The square crop adds a bit more interest but with the hair fading into the background it distracts.  The contrast is fairly nice between the jacket and skintones along with the hint of colour in the shirt.  Overall it is a nice image, just does not have the wow factor for me.', '2010-01-04 18:36:58.000000', NULL, 1),
(5795872, 842846, 16197, '<td valign="top">There is a lot going on here, however it was composed nicely.  The balance is almost perfect.  However for me it just does not pop enough and there only appears to be a very narrow focal plane which distracts from the image as a whole.  The colours might be pushed a bit as well as the depth of the clouds.  Overall it is nice just not quite there yet for me.</td>', 'There is a lot going on here, however it was composed nicely.  The balance is almost perfect.  However for me it just does not pop enough and there only appears to be a very narrow focal plane which distracts from the image as a whole.  The colours might be pushed a bit as well as the depth of the clouds.  Overall it is nice just not quite there yet for me.', '2010-01-04 18:38:16.000000', NULL, 1),
(5795876, 843130, 93565, '<td valign="top">Upon first glance, I thought the white horse was pulling him by the hood! Good job capturing a moment of interaction between child and animal. I think the scene could have been strengthened by concentrating on only the interaction between the boy and the brown horse though, as it is a great moment.</td>', 'Upon first glance, I thought the white horse was pulling him by the hood! Good job capturing a moment of interaction between child and animal. I think the scene could have been strengthened by concentrating on only the interaction between the boy and the brown horse though, as it is a great moment.', '2010-01-04 18:40:09.000000', NULL, 1),
(5795877, 841392, 16197, '<td valign="top">I enjoy these types of clouds.  So much character and personality in them.  The silhouettes of the trees are also nice.  However There is something missing here. Perhaps a huge push of colour and brightness would create much more interest.</td>', 'I enjoy these types of clouds.  So much character and personality in them.  The silhouettes of the trees are also nice.  However There is something missing here. Perhaps a huge push of colour and brightness would create much more interest.', '2010-01-04 18:40:21.000000', NULL, 1),
(5795880, 842241, 16197, '<td valign="top">Cute snapshot of the cat.  It appears a bit bright but it is fun and that is what matters.</td>', 'Cute snapshot of the cat.  It appears a bit bright but it is fun and that is what matters.', '2010-01-04 18:42:31.000000', NULL, 1),
(5795884, 841514, 93565, '<td valign="top">I don''t quite understand where you are going with this. I''m unsure of what your intended subject is, not because of the lack of focus, but because nothing has been accentuated by your choice of composition.</td>', 'I don''t quite understand where you are going with this. I''m unsure of what your intended subject is, not because of the lack of focus, but because nothing has been accentuated by your choice of composition.', '2010-01-04 18:45:00.000000', NULL, 1),
(5795886, 842836, 93565, '<td valign="top">Wow, that is one crazy lime green church. The colors of this are really unreal. The fisheye effect is pretty neat though, it really draws you into things.</td>', 'Wow, that is one crazy lime green church. The colors of this are really unreal. The fisheye effect is pretty neat though, it really draws you into things.', '2010-01-04 18:46:01.000000', NULL, 1),
(5795899, 840458, 93565, '<td valign="top">A more careful placing of the light filtering through the bridge would have made this a bombshell photo. Waiting for the light to illuminate the child''s face, for instance, would have been excellent. The blown patches on her dress serve as distractions instead of strengthening the scene using the ambient light. Having said that, the interaction and expressions are very good here.</td>', 'A more careful placing of the light filtering through the bridge would have made this a bombshell photo. Waiting for the light to illuminate the child''s face, for instance, would have been excellent. The blown patches on her dress serve as distractions instead of strengthening the scene using the ambient light. Having said that, the interaction and expressions are very good here.', '2010-01-04 18:53:49.000000', NULL, 1),
(5795903, 843181, 93565, '<td valign="top">I feel like this would have been a perfect moment to use a ND grad filter to darken the sky and keep it from blowing out. The house/building seems incidental instead of intentional.</td>', 'I feel like this would have been a perfect moment to use a ND grad filter to darken the sky and keep it from blowing out. The house/building seems incidental instead of intentional.', '2010-01-04 18:55:22.000000', NULL, 1),
(5795926, 842315, 16197, '<td valign="top">The colour contrast is nice but for me it is not pushed enough. As is the brightness of the image which feels dull to me.  The focal range I think is fine if the brightness and colours popped more.</td>', 'The colour contrast is nice but for me it is not pushed enough. As is the brightness of the image which feels dull to me.  The focal range I think is fine if the brightness and colours popped more.', '2010-01-04 19:05:54.000000', NULL, 1),
(5795931, 843134, 93565, '<td valign="top">I like the setting you''ve chosen. The bricks add a nice texture, and the soft lighting is pleasing to the eye. I wish there was a bit more emphasis to the person, but I still like it.</td>', 'I like the setting you''ve chosen. The bricks add a nice texture, and the soft lighting is pleasing to the eye. I wish there was a bit more emphasis to the person, but I still like it.', '2010-01-04 19:08:05.000000', NULL, 1),
(5795934, 842318, 93565, '<td valign="top">Another great Contre Jour photo! I bet this one could''ve taken top honors in that challenge. Great sky, and the poses are nice in conjunction with your title- the subjects seem rather retrospective. Great clouds, to boot.</td>', 'Another great Contre Jour photo! I bet this one could''ve taken top honors in that challenge. Great sky, and the poses are nice in conjunction with your title- the subjects seem rather retrospective. Great clouds, to boot.', '2010-01-04 19:09:30.000000', NULL, 1),
(5795935, 839961, 16197, '<td valign="top">I enjoy the concept of this piece, the silhouette is nicely done.  However for me there just is not enough wow factor.  it is nice, but not that nice.</td>', 'I enjoy the concept of this piece, the silhouette is nicely done.  However for me there just is not enough wow factor.  it is nice, but not that nice.', '2010-01-04 19:10:11.000000', NULL, 1),
(5795937, 843161, 93565, '<td valign="top">Interesting cardinal shot, but focus needs to be sharper. I think birds do better either tack sharp or blurred quite a bit by motion. This one is a bit in the no-man''s land between them. Nice action by the bird though, can''t say I''ve ever seen a bird do that.</td>', 'Interesting cardinal shot, but focus needs to be sharper. I think birds do better either tack sharp or blurred quite a bit by motion. This one is a bit in the no-man''s land between them. Nice action by the bird though, can''t say I''ve ever seen a bird do that.', '2010-01-04 19:11:10.000000', NULL, 1),
(5795938, 838039, 16197, '<td valign="top">This is an interesting concept.  It nearly appears as if the tree is floating in front of the earth.  Yet for me even though there is some nice visual tease here it just does not give me the emotional response I would have liked to get.</td>', 'This is an interesting concept.  It nearly appears as if the tree is floating in front of the earth.  Yet for me even though there is some nice visual tease here it just does not give me the emotional response I would have liked to get.', '2010-01-04 19:11:21.000000', NULL, 1),
(5795945, 841382, 16197, '<td valign="top">The shadowed elements here feel cold and dull the colours muted and boring in my opinion.  The yellow of the tree in the light really stands out and offers some brief glimpse of personality.  However as a whole I really find it lacking the wow factor.</td>', 'The shadowed elements here feel cold and dull the colours muted and boring in my opinion.  The yellow of the tree in the light really stands out and offers some brief glimpse of personality.  However as a whole I really find it lacking the wow factor.', '2010-01-04 19:13:14.000000', NULL, 1),
(5795961, 841842, 16197, '<td valign="top">Lovely sunset over the lake image. However it is common and for me it appears overly smoothed.  The rocks seem as if they are missing texture and as such part of their personality.  It is a nice image, just not for me.</td>', 'Lovely sunset over the lake image. However it is common and for me it appears overly smoothed.  The rocks seem as if they are missing texture and as such part of their personality.  It is a nice image, just not for me.', '2010-01-04 19:24:28.000000', NULL, 1),
(5795962, 842649, 16197, '<td valign="top">I enjoy the 70''s feel to this image.  It is a nice fun image which I am sure the expectant mother/father/friends/family really enjoy.  However for me, it is not enough to blow me away.  The wow factor is missing for me and this piece is just another nice portrait.</td>', 'I enjoy the 70''s feel to this image.  It is a nice fun image which I am sure the expectant mother/father/friends/family really enjoy.  However for me, it is not enough to blow me away.  The wow factor is missing for me and this piece is just another nice portrait.', '2010-01-04 19:25:41.000000', NULL, 1),
(5795968, 842926, 93565, '<td valign="top">This portrait is lacking interest in the subject matter. The subject isn''t actively engaged with the toy, but also isn''t actively posed. A capture of Jackie playing with the toy would have been stronger, or, alternatively, an all out posed shot. You could have used a black sheet or piece of velvet (ideally) for the dog to sit on and as a background for a portrait, with the camera''s point of view very low or perhaps have the dog sit up and have the shot from the dog''s eye level. Or an action shot, playing with the toy. The cabinet is a little bit distracting. Really, the main thing is that I think you''re probably getting hammered vote wise because this seems like a snapshot, largely because the dog''s posture really makes this seem like a quick posed shot with somebody camera right commanding the dog''s attention. Animals are perhaps more difficult than people to capture in portraits, because you can''t tell your dog to relax and not look posed. Keep at it though; on the bright side, animals never tire of posing :)</td>', 'This portrait is lacking interest in the subject matter. The subject isn''t actively engaged with the toy, but also isn''t actively posed. A capture of Jackie playing with the toy would have been stronger, or, alternatively, an all out posed shot. You could have used a black sheet or piece of velvet (ideally) for the dog to sit on and as a background for a portrait, with the camera''s point of view very low or perhaps have the dog sit up and have the shot from the dog''s eye level. Or an action shot, playing with the toy. The cabinet is a little bit distracting. Really, the main thing is that I think you''re probably getting hammered vote wise because this seems like a snapshot, largely because the dog''s posture really makes this seem like a quick posed shot with somebody camera right commanding the dog''s attention. Animals are perhaps more difficult than people to capture in portraits, because you can''t tell your dog to relax and not look posed. Keep at it though; on the bright side, animals never tire of posing :)', '2010-01-04 19:29:57.000000', NULL, 1),
(5795971, 840393, 16197, '<td valign="top">This is a nice night shot of the building lights.  It appears nice within the top colours, however with the windows on the right there appears to be a lot of noise.  It is a bit distracting and I am guessing you tried to brighten them to match the rest.  It si a lovely shot but for me it is lacking something extra.</td>', 'This is a nice night shot of the building lights.  It appears nice within the top colours, however with the windows on the right there appears to be a lot of noise.  It is a bit distracting and I am guessing you tried to brighten them to match the rest.  It si a lovely shot but for me it is lacking something extra.', '2010-01-04 19:31:47.000000', NULL, 1),
(5795972, 839423, 16197, '<td valign="top">A lovely night shot.  The lights appear to be working well with you as is the glow in the background to give you a bit of depth to the piece.  After looking the second time I am going to bump the score a bit because of the cleanness of the piece.</td>', 'A lovely night shot.  The lights appear to be working well with you as is the glow in the background to give you a bit of depth to the piece.  After looking the second time I am going to bump the score a bit because of the cleanness of the piece.', '2010-01-04 19:32:49.000000', NULL, 1),
(5795975, 841751, 16197, '<td valign="top">It is a nice cityscape though for me there is something that just does not sit well.  There almost appears to have a ''dreamy'' effect on it which blurs everything slightly.  I do enjoy the depth of detail in the trees.  However there is just something about this piece that does not work for me.  It just does not pop enough for me.  Perhaps the flat colours or lack of contrast.</td>', 'It is a nice cityscape though for me there is something that just does not sit well.  There almost appears to have a ''dreamy'' effect on it which blurs everything slightly.  I do enjoy the depth of detail in the trees.  However there is just something about this piece that does not work for me.  It just does not pop enough for me.  Perhaps the flat colours or lack of contrast.', '2010-01-04 19:34:16.000000', NULL, 1),
(5795976, 840458, 16197, '<td valign="top">This is a lovely family portrait and the selective colours works well, though you missed the spot over his shoulder and under her chin.  Also the flower/leaves between her feet have no real concept of belonging.  It does not make sense why they are there, much less in the middle of a bridge.  So for me the leaves are a major downside.  Otherwise it is a nice portrait and Im sure the couple would be excited to have this.  Though for me it just is not enough.</td>', 'This is a lovely family portrait and the selective colours works well, though you missed the spot over his shoulder and under her chin.  Also the flower/leaves between her feet have no real concept of belonging.  It does not make sense why they are there, much less in the middle of a bridge.  So for me the leaves are a major downside.  Otherwise it is a nice portrait and Im sure the couple would be excited to have this.  Though for me it just is not enough.', '2010-01-04 19:35:50.000000', NULL, 1),
(5795982, 843350, 93565, '<td valign="top">This reminds me sorta of another portrait I commented on...<a href="//www.dpchallenge.com/image.php?IMAGE_ID=756100" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_challenge/0-999/976/120/Copyrighted_Image_Reuse_Prohibited_756100.jpg'', strrpos(''//images.dpchallenge.com/images_challenge/0-999/976/120/Copyrighted_Image_Reuse_Prohibited_756100.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_challenge/0-999/976/120/Copyrighted_Image_Reuse_Prohibited_756100.jpg"/></a>. Pretty much everything I said there is true here (ironic if this ends up being the same photog lol). In addition, however, I''d like to see the bit of his head not chopped. I''d also consider bringing more of the motorcycle into the frame. It would strengthen things in regard to the "environmental portrait." I picture the shot being from low to the ground, looking up at the rider. Perhaps slightly backlit with fill light. I like everything about this except for the close crop.</td>', 'This reminds me sorta of another portrait I commented on.... Pretty much everything I said there is true here (ironic if this ends up being the same photog lol). In addition, however, I''d like to see the bit of his head not chopped. I''d also consider bringing more of the motorcycle into the frame. It would strengthen things in regard to the "environmental portrait." I picture the shot being from low to the ground, looking up at the rider. Perhaps slightly backlit with fill light. I like everything about this except for the close crop.', '2010-01-04 19:39:39.000000', NULL, 1),
(5796019, 843085, 93565, '<td valign="top">I enjoy the way the color of the stone contrasts with the rest of the scene. Having said that, I''m left wishing the falls comprised a larger portion of the scene. The golden light filtering through the trees is also a bit too bright and has blown. I think lowering your perspective would have helped to emphasize the falls as a subject matter.</td>', 'I enjoy the way the color of the stone contrasts with the rest of the scene. Having said that, I''m left wishing the falls comprised a larger portion of the scene. The golden light filtering through the trees is also a bit too bright and has blown. I think lowering your perspective would have helped to emphasize the falls as a subject matter.', '2010-01-04 20:01:49.000000', NULL, 1),
(5796022, 843255, 93565, '<td valign="top">Personally, I think your processing could have added quite a bit to this in order to accentuate the retro nature of the subject. A high contrast side lit shot in BW, some grain, or an aged sepia look, would all add to the retro nature of the shot.</td>', 'Personally, I think your processing could have added quite a bit to this in order to accentuate the retro nature of the subject. A high contrast side lit shot in BW, some grain, or an aged sepia look, would all add to the retro nature of the shot.', '2010-01-04 20:03:31.000000', NULL, 1),
(5796024, 838589, 93565, '<td valign="top">Good subject matter for a silhouette, but I would like seeing the full length of the trees, from the ground up to the sky.</td>', 'Good subject matter for a silhouette, but I would like seeing the full length of the trees, from the ground up to the sky.', '2010-01-04 20:04:37.000000', NULL, 1),
(5796031, 841948, 93565, '<td valign="top">Beautiful fine sand, nice golden light on the incoming surf. I like the silhouette on the rock. It seems as though you have some funkiness going on with the sand around your rock in the left foreground. It appears to be an aqua color...is this clipping? It would have been a simple clone job.</td>', 'Beautiful fine sand, nice golden light on the incoming surf. I like the silhouette on the rock. It seems as though you have some funkiness going on with the sand around your rock in the left foreground. It appears to be an aqua color...is this clipping? It would have been a simple clone job.', '2010-01-04 20:09:37.000000', NULL, 1),
(5796033, 842306, 76335, '<td valign="top">The contrast here feels a bit flat, which is further accentuated by your bleach white border.</td>', 'The contrast here feels a bit flat, which is further accentuated by your bleach white border.', '2010-01-04 20:10:19.000000', NULL, 1),
(5796035, 843310, 93565, '<td valign="top">I think this is a pretty cool shot. Getting the person totally in frame would have been nice, but I still like it. I personally would have also tried to decrease the impact of the snow falling in front of the lens right behind the fellow, as it is somewhat distracting and you have Advanced Editing at your disposal.</td>', 'I think this is a pretty cool shot. Getting the person totally in frame would have been nice, but I still like it. I personally would have also tried to decrease the impact of the snow falling in front of the lens right behind the fellow, as it is somewhat distracting and you have Advanced Editing at your disposal.', '2010-01-04 20:11:00.000000', NULL, 1),
(5796037, 843317, 76335, '<td valign="top">I hope this is doing well for you. I love shots like this, but more often than not, they seem to be lost on the voters here.</td>', 'I hope this is doing well for you. I love shots like this, but more often than not, they seem to be lost on the voters here.', '2010-01-04 20:11:51.000000', NULL, 1),
(5796038, 841537, 23484, '<td valign="top">Nice job on the panning.</td>', 'Nice job on the panning.', '2010-01-04 20:12:21.000000', NULL, 1),
(5796039, 843234, 23484, '<td valign="top">Nice shot. I like the way the light plays on the fur.</td>', 'Nice shot. I like the way the light plays on the fur.', '2010-01-04 20:13:08.000000', NULL, 1),
(5796042, 840048, 23484, '<td valign="top">I like the clouds.</td>', 'I like the clouds.', '2010-01-04 20:14:22.000000', NULL, 1),
(5796044, 837979, 23484, '<td valign="top">Now that''s a closeup.</td>', 'Now that''s a closeup.', '2010-01-04 20:15:26.000000', NULL, 1),
(5796047, 841680, 23484, '<td valign="top">Great shot and nice job on the B&amp;W processing.</td>', 'Great shot and nice job on the B&W processing.', '2010-01-04 20:16:29.000000', NULL, 1),
(5796048, 841701, 23484, '<td valign="top">Excellent job. I''ll bet that graffiti looks cool in the daylight.</td>', 'Excellent job. I''ll bet that graffiti looks cool in the daylight.', '2010-01-04 20:17:13.000000', NULL, 1),
(5796049, 843087, 93565, '<td valign="top">I like your shot. I think the crop at the top of the central zebra works well. However, I can only surmise that there was some reason to cut off the left zebra and leave the other chunk of a zebra to the right (the right zebra is what actually distracts me, the left one is alright). For the record, you might get voted down for your thick border, but I don''t personally find it excessive.</td>', 'I like your shot. I think the crop at the top of the central zebra works well. However, I can only surmise that there was some reason to cut off the left zebra and leave the other chunk of a zebra to the right (the right zebra is what actually distracts me, the left one is alright). For the record, you might get voted down for your thick border, but I don''t personally find it excessive.', '2010-01-04 20:17:20.000000', NULL, 1),
(5796050, 841447, 23484, '<td valign="top">I like the rays and the lights on top of the hills.</td>', 'I like the rays and the lights on top of the hills.', '2010-01-04 20:17:54.000000', NULL, 1),
(5796052, 841258, 23484, '<td valign="top">Great detail and focus.</td>', 'Great detail and focus.', '2010-01-04 20:18:25.000000', NULL, 1),
(5796055, 843174, 93565, '<td valign="top">Cool idea you''ve employed here. The selective desat is nice, but I''m left wishing that it was a different color. As is, it is somewhat distracting because it is so bright. I think angling it different so that the background was darker might have been more effective.</td>', 'Cool idea you''ve employed here. The selective desat is nice, but I''m left wishing that it was a different color. As is, it is somewhat distracting because it is so bright. I think angling it different so that the background was darker might have been more effective.', '2010-01-04 20:20:36.000000', NULL, 1),
(5796057, 843274, 93565, '<td valign="top">I have a hard time understanding why you chose to keep things out of focus. With such perfect leading lines, a low perspective shot with a short DoF, set close to the PoV, would have been much more effective for this scene. Those blue lines are perfect to use.</td>', 'I have a hard time understanding why you chose to keep things out of focus. With such perfect leading lines, a low perspective shot with a short DoF, set close to the PoV, would have been much more effective for this scene. Those blue lines are perfect to use.', '2010-01-04 20:22:23.000000', NULL, 1),
(5796064, 842710, 93565, '<td valign="top">The egret''s neck in this is really snake like. I like how you''ve managed to keep the head/eye of the bird in sharp focus, and decent focus for the feet. The blurred wings add a nice sense of speed, but I wish the areas on the bird''s wing and back weren''t blown and that the background were a bit more blurred. Having taken photos of birds, especially flying ones, I know your photo is still pretty damn good though, nitpicking aside.</td>', 'The egret''s neck in this is really snake like. I like how you''ve managed to keep the head/eye of the bird in sharp focus, and decent focus for the feet. The blurred wings add a nice sense of speed, but I wish the areas on the bird''s wing and back weren''t blown and that the background were a bit more blurred. Having taken photos of birds, especially flying ones, I know your photo is still pretty damn good though, nitpicking aside.', '2010-01-04 20:34:52.000000', NULL, 1),
(5796072, 841225, 93565, '<td valign="top">I really like the textures and huge variety of colors in your shot. The small anole (I''m guessing) is just the icing on the cake. Also, your vignette works perfectly for your subject matter by focusing the viewer on the lizard.. The little plant sprouting out by the tail is sorta cool too, adds some interest to the scene.</td>', 'I really like the textures and huge variety of colors in your shot. The small anole (I''m guessing) is just the icing on the cake. Also, your vignette works perfectly for your subject matter by focusing the viewer on the lizard.. The little plant sprouting out by the tail is sorta cool too, adds some interest to the scene.', '2010-01-04 20:43:20.000000', NULL, 1),
(5796083, 843320, 93565, '<td valign="top">I think this shot might have benefited from a BW treatment. The reason being, the colors are rather drab and definitely lacking in the vibrance department. This isn''t a problem, but it does make it particularly well suited for BW. It''s a nice pastoral scene, and the fog is a element.</td>', 'I think this shot might have benefited from a BW treatment. The reason being, the colors are rather drab and definitely lacking in the vibrance department. This isn''t a problem, but it does make it particularly well suited for BW. It''s a nice pastoral scene, and the fog is a element.', '2010-01-04 20:50:21.000000', NULL, 1),
(5796085, 843312, 16197, '<td valign="top">This isn''t too bad even with the amount of haze in the shot.  It actually has a pleasant balance.  However for me it just does not have a tremendous amount of pop.</td>', 'This isn''t too bad even with the amount of haze in the shot.  It actually has a pleasant balance.  However for me it just does not have a tremendous amount of pop.', '2010-01-04 20:52:54.000000', NULL, 1),
(5796088, 841447, 16197, '<td valign="top">I look at this and I want to like it more.  It has nice elements but it also have some not so nice elements.  Center composition for one does not thrill me.  The overly smooth feel of the image is a bit distracting.  I cannot tell what I am looking at on the foreground and there is such a huge amount of it it distracts from the overall image.</td>', 'I look at this and I want to like it more.  It has nice elements but it also have some not so nice elements.  Center composition for one does not thrill me.  The overly smooth feel of the image is a bit distracting.  I cannot tell what I am looking at on the foreground and there is such a huge amount of it it distracts from the overall image.', '2010-01-04 20:54:41.000000', NULL, 1),
(5796094, 843093, 16197, '<td valign="top">One of the better bird images in this challenge.  I am very happy to see the detail was left in the feathers and not smoothed over.  I also enjoy the contrasts and separation from background.  However I do not care for the profile view nor the fact there is no hint, idea, or concept of sunset except for your title.  For me it could be any time of day.  However Because with this second look I can see how much detail was left I will bump the score a bit.</td>', 'One of the better bird images in this challenge.  I am very happy to see the detail was left in the feathers and not smoothed over.  I also enjoy the contrasts and separation from background.  However I do not care for the profile view nor the fact there is no hint, idea, or concept of sunset except for your title.  For me it could be any time of day.  However Because with this second look I can see how much detail was left I will bump the score a bit.', '2010-01-04 20:56:23.000000', NULL, 1),
(5796096, 842630, 93565, '<td valign="top">Your white point is very off. The white of the snow is appearing as nearly 18% gray. As a result, your contrast is very compromised and decreases the impact of the photo. Additionally, including the tree tops would have been beneficial to this shot.</td>', 'Your white point is very off. The white of the snow is appearing as nearly 18% gray. As a result, your contrast is very compromised and decreases the impact of the photo. Additionally, including the tree tops would have been beneficial to this shot.', '2010-01-04 20:57:48.000000', NULL, 1),
(5796097, 840141, 16197, '<td valign="top">This piece has a strange feel for me.  I really want a sharp focus on something here.  Though it does not appear to be as sharp as it could be.  The yellow colour I can not tell if it is poor white balance management or the actual colour or you left it for effect.  It is a nice looking building however I feel with the snow and lighting it was done no justice.</td>', 'This piece has a strange feel for me.  I really want a sharp focus on something here.  Though it does not appear to be as sharp as it could be.  The yellow colour I can not tell if it is poor white balance management or the actual colour or you left it for effect.  It is a nice looking building however I feel with the snow and lighting it was done no justice.', '2010-01-04 20:58:15.000000', NULL, 1),
(5796102, 842883, 16197, '<td valign="top">Now this is an interesting find.  However your title is disconnected for me because it does not tell me tree, but perhaps tar something.  One may argue that you can see the tree on the bottom there, but one may also argue it does not really look like a tree most of us are used to seeing, nor can we see rings on the top which most of us would associate with a cut open tree.  The narrow focal plane also leaves me something to be desired as well as the clarity of image.</td>', 'Now this is an interesting find.  However your title is disconnected for me because it does not tell me tree, but perhaps tar something.  One may argue that you can see the tree on the bottom there, but one may also argue it does not really look like a tree most of us are used to seeing, nor can we see rings on the top which most of us would associate with a cut open tree.  The narrow focal plane also leaves me something to be desired as well as the clarity of image.', '2010-01-04 21:00:19.000000', NULL, 1),
(5796105, 839732, 16197, '<td valign="top">Now I can see some really fantastic potential for this image.  It appears all of the elements are there.  But for me, they are not pushed enough.  The clarity could be increased as well as sharpness and colour saturation.  However it is a very nice image and viewing it this second time I will offer a bit of a bump up.</td>', 'Now I can see some really fantastic potential for this image.  It appears all of the elements are there.  But for me, they are not pushed enough.  The clarity could be increased as well as sharpness and colour saturation.  However it is a very nice image and viewing it this second time I will offer a bit of a bump up.', '2010-01-04 21:01:57.000000', NULL, 1),
(5796106, 843118, 93565, '<td valign="top">You did decently to improve the scene, considering how high contrast your tones are here. I think you overdid the processing on the clouds a little bit, and you''ve got some very distinct haloing around your subjects. Beautiful country though.</td>', 'You did decently to improve the scene, considering how high contrast your tones are here. I think you overdid the processing on the clouds a little bit, and you''ve got some very distinct haloing around your subjects. Beautiful country though.', '2010-01-04 21:02:33.000000', NULL, 1),
(5796108, 842306, 16197, '<td valign="top">The first thing I notice is the complete lack of focus, like there was an attempt to make the image in the ''dreamy'' style.  The second thing I noticed is the complete lack of contrast as well as any sort of semblance of white which every element in this piece is screaming for.  It really feels bland, dull, faded and unappealing for me.</td>', 'The first thing I notice is the complete lack of focus, like there was an attempt to make the image in the ''dreamy'' style.  The second thing I noticed is the complete lack of contrast as well as any sort of semblance of white which every element in this piece is screaming for.  It really feels bland, dull, faded and unappealing for me.', '2010-01-04 21:03:28.000000', NULL, 1),
(5796132, 841915, 16197, '<td valign="top">I want to really like this piece.  But something just does not look right.  It appears the rocks have been smoothed over, perhaps they really look like that, huge globs of crafters clay.  Though for me I find it a bit distracting, and would have hoped for stranger visual characteristics. Also looking at the sky it is a bit noisy, and I would have liked that to be smoothed out more, with possible a bit of push on the colours over the overall image.  It is a nice find though.</td>', 'I want to really like this piece.  But something just does not look right.  It appears the rocks have been smoothed over, perhaps they really look like that, huge globs of crafters clay.  Though for me I find it a bit distracting, and would have hoped for stranger visual characteristics. Also looking at the sky it is a bit noisy, and I would have liked that to be smoothed out more, with possible a bit of push on the colours over the overall image.  It is a nice find though.', '2010-01-04 21:18:14.000000', NULL, 1),
(5796135, 843250, 16197, '<td valign="top">This is an overly all nice image.  The colours are nice, the silhouette is ok.  But for me it just does not wow me.  It is nice, but lacking the pop factor.</td>', 'This is an overly all nice image.  The colours are nice, the silhouette is ok.  But for me it just does not wow me.  It is nice, but lacking the pop factor.', '2010-01-04 21:19:19.000000', NULL, 1),
(5796138, 843167, 16197, '<td valign="top">A cute soft portrait I am sure the parents are happy to have.  However for me, it holds no appeal.  The face appears overly bright to the point of being blown out on that side and the complete lack of textures are distracting to me.  The dreamy effect used, or the blur is unappealing.</td>', 'A cute soft portrait I am sure the parents are happy to have.  However for me, it holds no appeal.  The face appears overly bright to the point of being blown out on that side and the complete lack of textures are distracting to me.  The dreamy effect used, or the blur is unappealing.', '2010-01-04 21:20:30.000000', NULL, 1),
(5796142, 843300, 93565, '<td valign="top">Nice portrait. BW conversion is excellent, and I like the candid nature of the shot.</td>', 'Nice portrait. BW conversion is excellent, and I like the candid nature of the shot.', '2010-01-04 21:22:21.000000', NULL, 1),
(5796143, 843084, 16197, '<td valign="top">Here is an image that has added a bit of character into the brickwork.  They sky leaves me wanting something else, but the center line of the building offers nice contrasts and personality.  The lower half is a bit too bright without so much and the top is overly dark.  If the centre effect was consistent throughout you would have had a much higher scoring image.  However i will slightly bump this second time through.</td>', 'Here is an image that has added a bit of character into the brickwork.  They sky leaves me wanting something else, but the center line of the building offers nice contrasts and personality.  The lower half is a bit too bright without so much and the top is overly dark.  If the centre effect was consistent throughout you would have had a much higher scoring image.  However i will slightly bump this second time through.', '2010-01-04 21:22:23.000000', NULL, 1),
(5796147, 842246, 93565, '<td valign="top">Good detail in the center, but either a more concerted effort to isolate the center from the rest of the photo as a focal point or a deeper DoF would have benefited things. Nice job capturing the drops, and the refracted image in the raindrop has some very cool color variation.</td>', 'Good detail in the center, but either a more concerted effort to isolate the center from the rest of the photo as a focal point or a deeper DoF would have benefited things. Nice job capturing the drops, and the refracted image in the raindrop has some very cool color variation.', '2010-01-04 21:24:11.000000', NULL, 1),
(5796173, 841915, 93565, '<td valign="top">The rock formation in your shot would benefit from a more close-up treatment I think. It would magnify the size as well as all the crenulations and variety of hue.</td>', 'The rock formation in your shot would benefit from a more close-up treatment I think. It would magnify the size as well as all the crenulations and variety of hue.', '2010-01-04 21:33:02.000000', NULL, 1),
(5796176, 842950, 16197, '<td valign="top">I really want to like this image, but for me it appears the white balance is completely off and the orangish shade of white that is over everything distracts me.  Also not being able to see the horses head is kind of off putting.  It is a nice find but for me it just doesn''t do anything.</td>', 'I really want to like this image, but for me it appears the white balance is completely off and the orangish shade of white that is over everything distracts me.  Also not being able to see the horses head is kind of off putting.  It is a nice find but for me it just doesn''t do anything.', '2010-01-04 21:34:20.000000', NULL, 1),
(5796179, 841865, 16197, '<td valign="top">A nice portrait for the parents.  However for me I don''t care for the monochromatic tone nor the flat straight lighting.  The eyes appear overly dark and with the rustish like colour I would guess not angel but the other side.  However as long as you are happy that is what matters.</td>', 'A nice portrait for the parents.  However for me I don''t care for the monochromatic tone nor the flat straight lighting.  The eyes appear overly dark and with the rustish like colour I would guess not angel but the other side.  However as long as you are happy that is what matters.', '2010-01-04 21:35:41.000000', NULL, 1),
(5796184, 842630, 16197, '<td valign="top">This has possibility of being something special.  However the lack of focus, the flat contrast and complete lack of clarity really put me off.  With the wonderful trees around there is such a scream for clarity and dark rich contrasts to create depth and character.  Though here, it is lacking for me.</td>', 'This has possibility of being something special.  However the lack of focus, the flat contrast and complete lack of clarity really put me off.  With the wonderful trees around there is such a scream for clarity and dark rich contrasts to create depth and character.  Though here, it is lacking for me.', '2010-01-04 21:37:01.000000', NULL, 1),
(5796188, 841070, 16197, '<td valign="top">I like the concept but I want something more.  For me here, it feels like a snapshot.  No real depth of imagery or story.  Being from CO I have a fond place in my heart for the Buggers. But this, I feel does no justice.</td>', 'I like the concept but I want something more.  For me here, it feels like a snapshot.  No real depth of imagery or story.  Being from CO I have a fond place in my heart for the Buggers. But this, I feel does no justice.', '2010-01-04 21:38:07.000000', NULL, 1),
(5796193, 841661, 16197, '<td valign="top">I enjoy this image more the second time through then the first.  Looking at it in more detail I enjoy the the aspect of the road and how it moves off.  The cloud is fun the sun is a bit distracting.  I feel with the right processing this image can be really spectacular.  Some tonal changes here, some sharpening there, a bit of colour push and it would be great.  However I will bump the score a touch for ya.</td>', 'I enjoy this image more the second time through then the first.  Looking at it in more detail I enjoy the the aspect of the road and how it moves off.  The cloud is fun the sun is a bit distracting.  I feel with the right processing this image can be really spectacular.  Some tonal changes here, some sharpening there, a bit of colour push and it would be great.  However I will bump the score a touch for ya.', '2010-01-04 21:40:40.000000', NULL, 1),
(5796197, 839137, 16197, '<td valign="top">I am sure the family will be happy with this piece.  Though not being a member I find the center composition to be a bit blah, as well as the flat colours and the back of the figures.  Also because the younger figure is holding the rifle in front and the older in back it distracts from the title because they are not exactly ''like'' each other.  Sure they are both out walking, I assume hunting but I lose something.</td>', 'I am sure the family will be happy with this piece.  Though not being a member I find the center composition to be a bit blah, as well as the flat colours and the back of the figures.  Also because the younger figure is holding the rifle in front and the older in back it distracts from the title because they are not exactly ''like'' each other.  Sure they are both out walking, I assume hunting but I lose something.', '2010-01-04 21:42:15.000000', NULL, 1),
(5796204, 839292, 93565, '<td valign="top">Neat pool you''ve captured here. Your choice of shutter length is great, capturing the flowing nature of the water but not over-exposing things. I''d like the "pearl" to not be cut off on the left, and in the top left, I wish that there wasn''t that bit of sky showing through the trees. I still really like the BW conversion on this though. Great capture.</td>', 'Neat pool you''ve captured here. Your choice of shutter length is great, capturing the flowing nature of the water but not over-exposing things. I''d like the "pearl" to not be cut off on the left, and in the top left, I wish that there wasn''t that bit of sky showing through the trees. I still really like the BW conversion on this though. Great capture.', '2010-01-04 21:49:29.000000', NULL, 1),
(5796205, 843148, 16197, '<td valign="top">Nice cute sports portrait.  Colours look nice and lighting works.  It is clean but for me it just isn''t there.  Don''t get me wrong I am sure the kiddo and his folks are tickled over the image.  Though for me, there just is not enough to really grab me and say HEY this is the one.</td>', 'Nice cute sports portrait.  Colours look nice and lighting works.  It is clean but for me it just isn''t there.  Don''t get me wrong I am sure the kiddo and his folks are tickled over the image.  Though for me, there just is not enough to really grab me and say HEY this is the one.', '2010-01-04 21:50:14.000000', NULL, 1),
(5796208, 843316, 16197, '<td valign="top">This location has so much personality so much character and so much potential that I can see from this piece it breaks my heart to look at this image.  The flat completely washed out colours of this piece literally erase the details and any interest that might have been there.  The only part of the image that even has any photographic integrity is the very bottom in the concrete and sand.  I would love to give this a really low score.  However being a free-study, perhaps this is your study so you get the benefit of the doubt.  But for this viewer, it does not work at all.</td>', 'This location has so much personality so much character and so much potential that I can see from this piece it breaks my heart to look at this image.  The flat completely washed out colours of this piece literally erase the details and any interest that might have been there.  The only part of the image that even has any photographic integrity is the very bottom in the concrete and sand.  I would love to give this a really low score.  However being a free-study, perhaps this is your study so you get the benefit of the doubt.  But for this viewer, it does not work at all.', '2010-01-04 21:53:15.000000', NULL, 1),
(5796209, 843168, 16197, '<td valign="top">Nice little critter you got there.  I assume it was difficult to capture however I would have loved to see more clarity of the fur as well as a bit more contrast to really make him/her pop out and say hello.</td>', 'Nice little critter you got there.  I assume it was difficult to capture however I would have loved to see more clarity of the fur as well as a bit more contrast to really make him/her pop out and say hello.', '2010-01-04 21:54:11.000000', NULL, 1),
(5796219, 842492, 16197, '<td valign="top">Classic type of image.  However I find the stick in the water near center frame to be completely distracting.  Because it offers the highest point of contrast it completely draws the eye away from any other detail.  However the boat and pier have nice range and if that stick was gone I feel it would really make this a stronger piece.</td>', 'Classic type of image.  However I find the stick in the water near center frame to be completely distracting.  Because it offers the highest point of contrast it completely draws the eye away from any other detail.  However the boat and pier have nice range and if that stick was gone I feel it would really make this a stronger piece.', '2010-01-04 22:00:49.000000', NULL, 1),
(5796220, 843280, 16739, '<td valign="top">very nice portrait</td>', 'very nice portrait', '2010-01-04 22:01:19.000000', NULL, 1),
(5796221, 841225, 16197, '<td valign="top">Interesting critter.  I really want to like the piece but for me it just feels out of focus and missing detail.  Sure there is a lot going on here but for me I would have liked a bit more separation and clarity.</td>', 'Interesting critter.  I really want to like the piece but for me it just feels out of focus and missing detail.  Sure there is a lot going on here but for me I would have liked a bit more separation and clarity.', '2010-01-04 22:01:39.000000', NULL, 1),
(5796223, 842883, 93565, '<td valign="top">The texture of the stump is interesting. I like how I can see the specific marks from the chainsaw, and the burned top. Having said that, I''m not too clear on why you cut the stump up as you did. I would prefer otherwise, myself. The black on the foreground is more rich, but I don''t think that''s a reason to cut off the less rich black in the background.</td>', 'The texture of the stump is interesting. I like how I can see the specific marks from the chainsaw, and the burned top. Having said that, I''m not too clear on why you cut the stump up as you did. I would prefer otherwise, myself. The black on the foreground is more rich, but I don''t think that''s a reason to cut off the less rich black in the background.', '2010-01-04 22:02:15.000000', NULL, 1),
(5796224, 841909, 16197, '<td valign="top">Nice flower image, I enjoy the crop used for this.  The pastel colours are nice however for me it does not pop enough.  Simple, delicate clean but does not wow me.</td>', 'Nice flower image, I enjoy the crop used for this.  The pastel colours are nice however for me it does not pop enough.  Simple, delicate clean but does not wow me.', '2010-01-04 22:02:23.000000', NULL, 1),
(5796227, 843201, 16197, '<td valign="top">No idea what the concept of this is.  No idea what the title says much less means.  All I see is an upside down image, from my perspective.  That being said, I don''t think this really is anything.  For me it does not say anything do anything and makes no sense.  I would pass by this every day and never notice it once.</td>', 'No idea what the concept of this is.  No idea what the title says much less means.  All I see is an upside down image, from my perspective.  That being said, I don''t think this really is anything.  For me it does not say anything do anything and makes no sense.  I would pass by this every day and never notice it once.', '2010-01-04 22:03:34.000000', NULL, 1),
(5796230, 841707, 16197, '<td valign="top">Interesting makeup.  Makes me want to see more from the shoot.  However for me and this image it appears overly soft, it distracts my eye.  It feels like something is missing, maybe a bit of contrast, or even more personality of expression.  It is interesting but does not wow me.</td>', 'Interesting makeup.  Makes me want to see more from the shoot.  However for me and this image it appears overly soft, it distracts my eye.  It feels like something is missing, maybe a bit of contrast, or even more personality of expression.  It is interesting but does not wow me.', '2010-01-04 22:04:42.000000', NULL, 1),
(5796231, 841561, 16197, '<td valign="top">One of the better clean portraits in this challenge.  Clarity colours lighting all work out nicely.  I am sure the owners are thrilled with this in their hands.  However for me, it really is just another portrait without much else to keep me interested.  Yet, after really looking at a few others I will bump this up a bit because it does have nice technical skill.</td>', 'One of the better clean portraits in this challenge.  Clarity colours lighting all work out nicely.  I am sure the owners are thrilled with this in their hands.  However for me, it really is just another portrait without much else to keep me interested.  Yet, after really looking at a few others I will bump this up a bit because it does have nice technical skill.', '2010-01-04 22:06:00.000000', NULL, 1),
(5796232, 841497, 16197, '<td valign="top">I like the concept but I feel it did not work.  I think I find the most distracting is the narrow focal range as well as the camera angle of the image.  I would like something a bit more dramatic with much more clarity.  However that being said the red and blue work well to contrast and if there gave more blue on the ice I think it would have really popped more.</td>', 'I like the concept but I feel it did not work.  I think I find the most distracting is the narrow focal range as well as the camera angle of the image.  I would like something a bit more dramatic with much more clarity.  However that being said the red and blue work well to contrast and if there gave more blue on the ice I think it would have really popped more.', '2010-01-04 22:07:09.000000', NULL, 1),
(5796234, 842589, 16197, '<td valign="top">Little quack''r in the pond.  I find that the side foliage here seems to be sharper focus then the duck.  Also the near center composition leaves me wanting something more.  I would have liked a bit more separation as well as depth with the feller.</td>', 'Little quack''r in the pond.  I find that the side foliage here seems to be sharper focus then the duck.  Also the near center composition leaves me wanting something more.  I would have liked a bit more separation as well as depth with the feller.', '2010-01-04 22:08:43.000000', NULL, 1),
(5796236, 841213, 16197, '<td valign="top">Interesting perspective though it hardly looks like day.  The orange cast over everything for me is a bit distracting.  Specially when there is the coloured blue squares at the bottom.  It is an interesting perspective though I feel it could be something more, specially if it was captured during the day.</td>', 'Interesting perspective though it hardly looks like day.  The orange cast over everything for me is a bit distracting.  Specially when there is the coloured blue squares at the bottom.  It is an interesting perspective though I feel it could be something more, specially if it was captured during the day.', '2010-01-04 22:10:03.000000', NULL, 1),
(5796238, 837730, 16197, '<td valign="top">The first thing I notice is the ''dreamy'' effect.  For me it really distracts from the image.  The slight blur over everything reduces the clarity I crave.  The colours are nice from the blues and greens however the large unappealing clouds seem to have been forgotten during post.  Overall for me it is an ok image but does nothing for me.</td>', 'The first thing I notice is the ''dreamy'' effect.  For me it really distracts from the image.  The slight blur over everything reduces the clarity I crave.  The colours are nice from the blues and greens however the large unappealing clouds seem to have been forgotten during post.  Overall for me it is an ok image but does nothing for me.', '2010-01-04 22:11:23.000000', NULL, 1),
(5796241, 842989, 16197, '<td valign="top">First thing I notice is the noise/texture across the skin.  It also moves into the wall behind her so I know it is not skin texture.  The hair seems blurred as if in motion, and the lighting may have been facilitated in post hence the noise.  For me this straight on view is not appealing and does not flatter the model.  It is an ok portrait but does nothing for me.</td>', 'First thing I notice is the noise/texture across the skin.  It also moves into the wall behind her so I know it is not skin texture.  The hair seems blurred as if in motion, and the lighting may have been facilitated in post hence the noise.  For me this straight on view is not appealing and does not flatter the model.  It is an ok portrait but does nothing for me.', '2010-01-04 22:13:06.000000', NULL, 1),
(5796255, 841537, 16197, '<td valign="top">Fun image. I bet the rider and stuff are excited about it.  The motion blur looks nice and the near focus of the rider/cart work well.  Though for me, it just does not push it far enough to keep my attention.  it is nice and well done but not enough for me.</td>', 'Fun image. I bet the rider and stuff are excited about it.  The motion blur looks nice and the near focus of the rider/cart work well.  Though for me, it just does not push it far enough to keep my attention.  it is nice and well done but not enough for me.', '2010-01-04 22:20:37.000000', NULL, 1),
(5796259, 843092, 16197, '<td valign="top">What a cute fella.  I think this is a nice piece, cropped well and the colours are nice.  I enjoy the clarity of fur/feathers as well as the focal range.  After looking this second time I will bump the score a bit.  However it does lack a strong wow factor for me.</td>', 'What a cute fella.  I think this is a nice piece, cropped well and the colours are nice.  I enjoy the clarity of fur/feathers as well as the focal range.  After looking this second time I will bump the score a bit.  However it does lack a strong wow factor for me.', '2010-01-04 22:21:50.000000', NULL, 1),
(5796265, 841754, 16197, '<td valign="top">Interesting capture.  I really enjoy the mood and feel to this piece.  I think I will bump this up a bit more on this second view.  I think my largest complaint about it will be that the vignette is way to dark.  Less of course this was shot with a spotlight or something else that created the circle effect then I would say to have opened it up a bit more and not created it so dark.</td>', 'Interesting capture.  I really enjoy the mood and feel to this piece.  I think I will bump this up a bit more on this second view.  I think my largest complaint about it will be that the vignette is way to dark.  Less of course this was shot with a spotlight or something else that created the circle effect then I would say to have opened it up a bit more and not created it so dark.', '2010-01-04 22:23:27.000000', NULL, 1),
(5796272, 838353, 16197, '<td valign="top">Nice find, but for me it does not give me much interest.  There is a small bit, less then a quarter of the image that offers any interest for the viewer.  The rest is flat and dull without personality.</td>', 'Nice find, but for me it does not give me much interest.  There is a small bit, less then a quarter of the image that offers any interest for the viewer.  The rest is flat and dull without personality.', '2010-01-04 22:24:39.000000', NULL, 1),
(5796275, 843123, 16197, '<td valign="top">The colours here have potential.  However the center composition is distracting.  I would have liked to see the sun more to the right to open up some of the blue sky there for colour contrasts.</td>', 'The colours here have potential.  However the center composition is distracting.  I would have liked to see the sun more to the right to open up some of the blue sky there for colour contrasts.', '2010-01-04 22:25:31.000000', NULL, 1),
(5796279, 841037, 16197, '<td valign="top">The overly smoothed aspect of this image is a complete turnoff for me.  It distracts the eye and gives me personally no feeling of anything.  It seems there is great potential here for something grand.  The colours could be something amazing, yet being overly smoothed they become flat and the detail is completely last.</td>', 'The overly smoothed aspect of this image is a complete turnoff for me.  It distracts the eye and gives me personally no feeling of anything.  It seems there is great potential here for something grand.  The colours could be something amazing, yet being overly smoothed they become flat and the detail is completely last.', '2010-01-04 22:26:42.000000', NULL, 1),
(5796282, 842846, 37444, '<td valign="top">Waimea Canyon? Love the colors.</td>', 'Waimea Canyon? Love the colors.', '2010-01-04 22:27:32.000000', NULL, 1),
(5796284, 843274, 16197, '<td valign="top">I am sure every comment is the same, out of focus.  It is, that part is obvious.  However for me, I look and feel those streams of blue light distract me as well.  At least the ones directly in front of me which create the center composition which is unappealing.   I know how difficult these can be handheld, which I am assuming this is.  Yet still...</td>', 'I am sure every comment is the same, out of focus.  It is, that part is obvious.  However for me, I look and feel those streams of blue light distract me as well.  At least the ones directly in front of me which create the center composition which is unappealing.   I know how difficult these can be handheld, which I am assuming this is.  Yet still...', '2010-01-04 22:28:10.000000', NULL, 1),
(5796288, 841514, 16197, '<td valign="top">I kinda like the concept here.  it almost works.  If I could see a bit more of the glass/window you are looking through I think it would really have been a nice added element that portrays an creative idea.  However as it is now, the blurred image is mildly interesting.</td>', 'I kinda like the concept here.  it almost works.  If I could see a bit more of the glass/window you are looking through I think it would really have been a nice added element that portrays an creative idea.  However as it is now, the blurred image is mildly interesting.', '2010-01-04 22:29:44.000000', NULL, 1),
(5796294, 842946, 37444, '<td valign="top">stunning 10</td>', 'stunning 10', '2010-01-04 22:31:05.000000', NULL, 1),
(5796296, 841642, 16197, '<td valign="top">Interesting image.  The light appears to be just camera right, nearly on camera and for me a bit unappealing.  I also look at this and wonder where the story is, why is the model here why is she squatting like that, what is she wearing those cloths?  I would hope for something stronger, something with more of a story.  For me here, this does not do much.</td>', 'Interesting image.  The light appears to be just camera right, nearly on camera and for me a bit unappealing.  I also look at this and wonder where the story is, why is the model here why is she squatting like that, what is she wearing those cloths?  I would hope for something stronger, something with more of a story.  For me here, this does not do much.', '2010-01-04 22:31:27.000000', NULL, 1),
(5796298, 843109, 93565, '<td valign="top">Lol. The stare from this wee one is great, and I enjoy the vignette. I''m not usually a fan of young child portraits, but I enjoy the expression here.</td>', 'Lol. The stare from this wee one is great, and I enjoy the vignette. I''m not usually a fan of young child portraits, but I enjoy the expression here.', '2010-01-04 22:31:48.000000', NULL, 1),
(5796310, 841844, 16197, '<td valign="top">The colour of the water is nice and rich, however there is a noise I see which distracts me and the goose seems to be a bit out of focus.  I would have enjoyed a much higher clarity of the critter as well as a bit more interest in pose, maybe leaving the complete reflection in as apposed to the chopped off head here.</td>', 'The colour of the water is nice and rich, however there is a noise I see which distracts me and the goose seems to be a bit out of focus.  I would have enjoyed a much higher clarity of the critter as well as a bit more interest in pose, maybe leaving the complete reflection in as apposed to the chopped off head here.', '2010-01-04 22:36:23.000000', NULL, 1),
(5796316, 840298, 19641, '<td valign="top">Beautiful!!  Wish I could take portraits this clear!  I love the eyes however the makeup in the corner of her eye looks a little funny to me.</td>', 'Beautiful!!  Wish I could take portraits this clear!  I love the eyes however the makeup in the corner of her eye looks a little funny to me.', '2010-01-04 22:37:55.000000', NULL, 1),
