(5801450, 841679, 67697, '<td valign="top">So sweet.  I love the light and shadow.  The light is reflecting up beautifully on the kitty.</td>', 'So sweet.  I love the light and shadow.  The light is reflecting up beautifully on the kitty.', '2010-01-07 22:19:18.000000', NULL, 1),
(5801452, 842946, 61961, '<td valign="top">I''m guessing this will be a ribbon winner (a top-ten for sure).   Awesome exposure.</td>', 'I''m guessing this will be a ribbon winner (a top-ten for sure).   Awesome exposure.', '2010-01-07 22:19:25.000000', NULL, 1),
(5801453, 843166, 61961, '<td valign="top">Though some credit must be given to your beautiful model, my amateur eye can''t detect any problems with this photo.</td>', 'Though some credit must be given to your beautiful model, my amateur eye can''t detect any problems with this photo.', '2010-01-07 22:19:29.000000', NULL, 1),
(5801454, 840597, 61961, '<td valign="top">I''m rarely a fan of selective desaturation, but you''ve used it well and creatively.  Striking photo.</td>', 'I''m rarely a fan of selective desaturation, but you''ve used it well and creatively.  Striking photo.', '2010-01-07 22:19:31.000000', NULL, 1),
